window.THABAT_STATIONS = [

/* ───────────── 1 · The Boy & the People of the Ditch ───────────── */
{
  id:'ghulam', num:1, icon:'🧒', emoji:'🔥', color:'#C0392B',
  title:{ ar:'الغُلامُ وأصحابُ الأُخدود', en:'The Boy & the People of the Ditch' },
  narration:{
    ar:'أهلاً بِكَ في رِحلةِ الأبطال! 🔥 وأوَّلُ بَطَلٍ هو <b>غُلامٌ صَغيرٌ مِثلُك</b>، حَكى قِصَّتَهُ النَّبِيُّ ﷺ كامِلة (رواه مسلم). كانَ هُناكَ مَلِكٌ ظالِمٌ يُجبِرُ النّاسَ على عِبادَتِهِ مِن دونِ الله، وكانَ لَهُ ساحِرٌ شَيخٌ يُعَلِّمُ غُلاماً صَغيراً السِّحر. لكنَّ الغُلامَ التَقى في طَريقِهِ بِراهِبٍ مُؤمِنٍ، فَعَلَّمَهُ الإيمانَ بِاللهِ الواحِد، فَآمَنَ قَلبُهُ الصَّغير. وصارَ اللهُ يُجري على يَدَيهِ عَجائِبَ: يَشفي الأعمى والأبرَصَ بِدُعائِهِ — ويَقولُ دائِماً: «أنا لا أشفي، إنَّما <b>يَشفي الله</b>». وعَرَفَ المَلِكُ بِأمرِهِ فَعَذَّبَهُ، فَلَم يَترُك إيمانَه. حاوَلَ المَلِكُ قَتلَهُ مَرّاتٍ فَيَحفَظُهُ الله! فَقالَ الغُلامُ كَلِمةً عَجيبة: «لَن تَستَطيعَ قَتلي حتّى تَجمَعَ النّاسَ وتَقولَ: <b>بِسمِ اللهِ رَبِّ الغُلام</b>». فَفَعَلَ المَلِك، فَماتَ الغُلام — لكِن ماذا حَدَث؟ صاحَ النّاسُ كُلُّهُم: «آمَنّا بِرَبِّ الغُلام»! بَطَلٌ صَغيرٌ ضَحّى بِحَياتِهِ فَآمَنَت مَدينةٌ كامِلة! فَغَضِبَ المَلِكُ وحَفَرَ حُفَراً عَظيمةً (الأُخدود) وأشعَلَ فيها النّار، وألقى المُؤمِنينَ فيها، فَثَبَتوا ولم يَرجِعوا.',
    en:'Welcome to the Journey of the Heroes! 🔥 The first hero is <b>a young boy like you</b>, whose story the Prophet ﷺ told in full (Muslim). There was a tyrant king who forced people to worship him instead of Allah, and he had an old sorcerer teaching a young boy magic. But on his way the boy met a believing monk who taught him to believe in the One God, and his little heart believed. Allah began working wonders through him: he healed the blind and the leper by his prayer — always saying: "I do not heal; only <b>Allah heals</b>." The king learned of him and tortured him, yet the boy never abandoned his faith. The king tried to kill him several times, and Allah kept saving him! So the boy said something amazing: "You will not be able to kill me until you gather the people and say: <b>In the name of Allah, the Lord of the boy</b>." The king did so, and the boy died — but what happened? All the people cried out: "We believe in the Lord of the boy!" A young hero sacrificed his life and a whole city believed! The king, enraged, dug great pits (the ditch), lit fire in them, and threw the believers in — and they stood firm and never turned back.' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ يُضَحّي طِفلٌ صَغيرٌ بِحَياتِهِ مِن أجلِ إيمانِه؟» 🤔', en:'A question crosses your mind: "How could a little child sacrifice his life for his faith?" 🤔' },
  logic:{
    ar:'لِأنَّ الغُلامَ عَرَفَ سِرّاً عَظيماً: أنَّ <b>الحَياةَ الحَقيقيّةَ هي الآخِرة</b>، وأنَّ هِدايةَ النّاسِ أغلى مِن حَياةٍ واحِدةٍ تَنتَهي. هو لم يُفَكِّر «أنا فَقَط»، بَل فَكَّرَ «كَيفَ يَهتَدي قَومي كُلُّهُم؟». ودَرسُ القِصّةِ لَكَ أنت: لَستَ صَغيراً على الإيمانِ القَوِيّ! الإيمانُ لَيسَ مَقاساً لِلكِبارِ فَقَط — قَلبُ الطِّفلِ يَتَّسِعُ لِأعظَمِ يَقين. ولاحِظ شَيئاً: الغُلامُ كانَ يَنسِبُ الشِّفاءَ للهِ دائِماً، لم يَتَكَبَّر يَوماً ويَقُل «أنا». هذا هو البَطَلُ الحَقيقيّ: قَوِيٌّ بِاللهِ، مُتَواضِعٌ لِله. وثَمَرةُ ثَباتِهِ أنَّ اللهَ خَلَّدَ قِصَّتَهُ في القُرآنِ في سورةِ البُروج، يَقرَؤُها المُسلِمونَ إلى اليوم — ماتَ جَسَدُهُ وعاشَت قِصَّتُهُ تُلهِمُ مَلايينَ القُلوب!',
    en:'Because the boy knew a great secret: that <b>true life is the Hereafter</b>, and that guiding people is more precious than one life that ends. He didn\'t think "only me"; he thought "how can my whole people be guided?" And the story\'s lesson is for you: you are not too young for strong faith! Faith isn\'t a size for grown-ups only — a child\'s heart can hold the greatest certainty. Notice something: the boy always attributed healing to Allah; he never grew proud and said "I." That is the true hero: strong through Allah, humble before Allah. And the fruit of his steadfastness is that Allah immortalized his story in the Quran, in Surah Al-Buruj, which Muslims still read today — his body died and his story lived on, inspiring millions of hearts!' },
  myth:{ claim:{ ar:'«الأطفالُ صِغارٌ على الإيمانِ القَوِيّ والمَواقِفِ العَظيمة!»', en:'"Children are too small for strong faith and great stands!"' },
         bust:{ ar:'غُلامٌ صَغيرٌ آمَنَ بِاللهِ فَهَدى اللهُ بِهِ مَدينةً كامِلة، وخَلَّدَ قِصَّتَهُ في القُرآن — قَلبُ الطِّفلِ يَتَّسِعُ لِأعظَمِ يَقين.', en:'A young boy believed in Allah, and through him Allah guided a whole city, immortalizing his story in the Quran — a child\'s heart can hold the greatest certainty.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'الغُلام',en:'The boy'}, job:{ar:'بَطَلٌ صَغيرٌ ثَبَتَ على إيمانِه',en:'A young hero firm in his faith'} },
      { tool:{ar:'الرّاهِب',en:'The monk'}, job:{ar:'عَلَّمَهُ الإيمانَ بِاللهِ الواحِد',en:'Taught him faith in the One God'} },
      { tool:{ar:'«بِسمِ اللهِ رَبِّ الغُلام»',en:'"In the name of Allah, Lord of the boy"'}, job:{ar:'الكَلِمةُ التي آمَنَ بِها النّاس',en:'The words that made the people believe'} },
      { tool:{ar:'الأُخدود',en:'The ditch'}, job:{ar:'نارٌ ثَبَتَ عِندَها المُؤمِنون',en:'A fire where the believers stood firm'} },
    ] },
  reflection:{
    ayah:'﴿قُتِلَ أَصْحَابُ الْأُخْدُودِ ۝ النَّارِ ذَاتِ الْوَقُودِ ۝ إِذْ هُمْ عَلَيْهَا قُعُودٌ ۝ وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ﴾',
    ref:{ ar:'سورة البُروج · ٤–٧', en:'Surah Al-Buruj · 4–7' },
    explain:{
      ar:'لَعَنَ اللهُ الظّالِمينَ الذينَ حَفَروا الأُخدودَ وأحرَقوا المُؤمِنين. لكنِ انتَبِه: مَن الذي خَلَّدَهُ القُرآنُ بِالكَرامةِ والثَّناء؟ <b>المُؤمِنونَ الثّابِتون</b>، لا المَلِكُ الظّالِمُ الذي صارَ مَلعوناً! الظّالِمُ يَملِكُ النّارَ لِأيّامٍ، والمُؤمِنُ يَملِكُ الجَنّةَ إلى الأبَد. فَالثَّباتُ على الحَقِّ هو الرِّبحُ الحَقيقيّ، مَهما بَدا في الدُّنيا خَسارة. وهذِهِ أوَّلُ بُطولةٍ في رِحلَتِنا: أن تَثبُتَ على إيمانِكَ مَهما كانَ الثَّمَن.',
      en:'Allah cursed the oppressors who dug the ditch and burned the believers. But notice: whom did the Quran immortalize with honor and praise? <b>The steadfast believers</b>, not the tyrant king who became cursed! The oppressor owns the fire for days; the believer owns Paradise forever. Steadfastness upon the truth is the real profit, however much it looks like loss in this world. And this is the first heroism of our journey: that you stand firm on your faith whatever the price.' } },
  card:{ name:{ar:'الغُلامُ المُؤمِن',en:'The Believing Boy'}, meaning:{ar:'طِفلٌ صَغيرٌ ثَبَتَ على إيمانِهِ حتّى الفِداء، فَهَدى اللهُ بِهِ مَدينةً كامِلة — دَليلٌ أنَّ الطِّفلَ يَكونُ بَطَلَ إيمان',en:'A young child who stood firm in his faith to the point of sacrifice, and through him Allah guided a whole city — proof that a child can be a hero of faith'} },
  proof:{ ar:'لَستُ صَغيراً على الإيمانِ القَوِيّ — قَلبُ الطِّفلِ يَتَّسِعُ لِأعظَمِ يَقين', en:'I\'m not too young for strong faith — a child\'s heart holds the greatest certainty' },
  dua:{ ar:'اللهُمَّ ثَبِّتني على دينِكَ كَما ثَبَّتَّ الغُلامَ المُؤمِن', en:'O Allah, keep me firm on Your religion as You kept the believing boy firm' },
  mission:{ ar:'🧒 مُهِمّةُ البُطولة: الغُلامُ كانَ يَقولُ «اللهُ يَشفي». تَدَرَّب اليومَ على نِسبةِ كُلِّ خَيرٍ لِله: حينَ تَنجَحُ قُل «بِفَضلِ الله»، وحينَ تُعطَى شَيئاً قُل «الحَمدُ لِله» — هكذا يُفَكِّرُ الأبطال.', en:'🧒 Hero Mission: The boy always said "Allah heals." Practice today attributing every good to Allah: when you succeed say "by Allah\'s grace," when given something say "alhamdulillah" — that\'s how heroes think.' },
  badge:{ icon:'🔥', color:'#C0392B', title:{ ar:'بَطَلُ الفِداء', en:'Hero of Sacrifice' } }
},

/* ───────────── 2 · The Youth of the Cave ───────────── */
{
  id:'kahf', num:2, icon:'🕳️', emoji:'🐕', color:'#2C7A6B',
  title:{ ar:'فِتيةُ الكَهف — شَبابٌ آمَنوا بِرَبِّهِم', en:'The Youth of the Cave — Young Believers' },
  narration:{
    ar:'بَطَلُنا اليومَ <b>مَجموعةُ شَبابٍ</b> خَلَّدَ اللهُ قِصَّتَهُم في سورةٍ كامِلةٍ نَقرَؤُها كُلَّ جُمُعة: سورةُ الكَهف! 🕳️ عاشوا في مَدينةٍ يَعبُدُ أهلُها الأصنامَ، ويَحكُمُها مَلِكٌ جَبّارٌ يَقتُلُ كُلَّ مَن يُؤمِنُ بِاللهِ الواحِد. لكنَّ هؤلاءِ الفِتيةَ فَكَّروا بِعُقولِهِم فَعَرَفوا أنَّ هذِهِ الأصنامَ الحَجَرِيّةَ لا تَنفَعُ ولا تَضُرّ، وأنَّ الرَّبَّ الحَقيقيَّ هو خالِقُ السَّماواتِ والأرض. فَوَقَفوا وَقفةً شُجاعةً وقالوا: ﴿<b>رَبُّنا رَبُّ السَّماواتِ والأرضِ لَن نَدعُوَ مِن دونِهِ إلهاً</b>﴾. ولَمّا اشتَدَّ علَيهِمُ الخَطَر، تَرَكوا بُيوتَهُم ومالَهُم ولَجَؤوا إلى <b>كَهفٍ</b> في الجَبَل، وقالوا: ﴿رَبَّنا آتِنا مِن لَدُنكَ رَحمةً وهَيِّئ لَنا مِن أمرِنا رَشَداً﴾. فَأنامَهُمُ اللهُ في الكَهفِ نَوماً عَجيباً <b>ثَلاثَمِئةٍ وتِسعَ سِنين</b>! وحَفِظَهُم بِكَلبِهِم على البابِ يَحرُسُهُم. ثُمَّ أيقَظَهُم بَعدَ أن ماتَ المَلِكُ الظّالِمُ وصارَتِ المَدينةُ مُؤمِنة — فَصاروا آيةً على قُدرةِ اللهِ في حِفظِ أولِيائِه.',
    en:'Today\'s hero is <b>a group of young men</b> whose story Allah immortalized in a whole surah we read every Friday: Surah Al-Kahf! 🕳️ They lived in a city whose people worshipped idols, ruled by a tyrant king who killed anyone who believed in the One God. But these youths thought with their minds and realized these stone idols could neither benefit nor harm, and that the true Lord is the Creator of the heavens and earth. So they took a brave stand and said: ﴾<b>Our Lord is the Lord of the heavens and the earth; we will never call upon any god besides Him</b>﴿. When the danger grew severe, they left their homes and wealth and took refuge in a <b>cave</b> in the mountain, saying: ﴾Our Lord, grant us mercy from Yourself and guide us rightly in our affair﴿. So Allah put them to sleep in the cave a wondrous sleep — <b>three hundred and nine years</b>! He guarded them with their dog at the entrance keeping watch. Then He woke them after the tyrant king had died and the city had become believing — and they became a sign of Allah\'s power to protect His friends.' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «لِماذا تَرَكوا بُيوتَهُم وكُلَّ شَيءٍ مِن أجلِ الدّين؟» 🤔', en:'A question crosses your mind: "Why did they leave their homes and everything for their religion?" 🤔' },
  logic:{
    ar:'لِأنَّهُم فَهِموا قاعِدةَ الأبطال: <b>الدّينُ أغلى مِن كُلِّ شَيء</b>. البَيتُ والمالُ يُمكِنُ تَعويضُهُما، أمّا الإيمانُ فإذا ضاعَ ضاعَ كُلُّ شَيء. وانظُر كَيفَ كافَأَهُمُ اللهُ على شَجاعَتِهِم: تَرَكوا بُيوتاً صَغيرةً فَأعطاهُمُ اللهُ حِمايةً لا يَملِكُها أعظَمُ المُلوك، وخَلَّدَ ذِكرَهُم في كِتابٍ يُتلى إلى يَومِ القِيامة! ولاحِظ ثَلاثةَ دُروسٍ ذَكِيّة: أوَّلاً، هؤلاءِ <b>شَبابٌ</b> — والشَّبابُ والأطفالُ هُم أبطالُ التَّغيير. ثانِياً، لَمّا عَجَزوا عن مُواجَهةِ الظُّلمِ مُباشَرةً <b>ابتَعَدوا عنهُ</b> لِيَحفَظوا دينَهُم — وهذا حِكمةٌ لا جُبن. ثالِثاً، توَكَّلوا على اللهِ بِالدُّعاءِ فَكَفاهُم. حينَ تَكونُ مَعَ مَجموعةٍ تَدعوكَ لِلخَطَأ، تَذَكَّر فِتيةَ الكَهف: ابتَعِد عن السّوءِ وتَوَكَّل على الله، فالرِّفقةُ الصّالِحةُ كَنزٌ والثَّباتُ مَعَها أسهَل.',
    en:'Because they understood the heroes\' rule: <b>religion is more precious than everything</b>. A house and money can be replaced, but if faith is lost, everything is lost. See how Allah rewarded their courage: they left small homes, and Allah gave them protection that the greatest kings don\'t possess, and immortalized them in a Book recited until the Day of Resurrection! Notice three clever lessons: first, these were <b>young people</b> — youth and children are the heroes of change. Second, when they couldn\'t confront the oppression directly, they <b>distanced themselves from it</b> to protect their faith — that\'s wisdom, not cowardice. Third, they relied on Allah with du\'a, and He sufficed them. When you\'re with a group urging you to do wrong, remember the youth of the cave: step away from evil and trust Allah; righteous company is a treasure, and steadfastness is easier with it.' },
  myth:{ claim:{ ar:'«الابتِعادُ عنِ الأصدِقاءِ السَّيِّئينَ ضَعفٌ وخَوف!»', en:'"Walking away from bad friends is weakness and fear!"' },
         bust:{ ar:'فِتيةُ الكَهفِ ابتَعَدوا عنِ الظُّلمِ لِيَحفَظوا دينَهُم، فَحَفِظَهُمُ اللهُ وخَلَّدَ ذِكرَهُم. تَركُ السّوءِ حِكمةٌ وشَجاعة، لا جُبن.', en:'The youth of the cave distanced themselves from evil to protect their faith, so Allah protected them and immortalized them. Leaving wrong is wisdom and courage, not cowardice.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'الفِتية',en:'The youths'}, job:{ar:'شَبابٌ آمَنوا بِرَبِّهِم وثَبَتوا',en:'Young men who believed and held firm'} },
      { tool:{ar:'الكَهف',en:'The cave'}, job:{ar:'مَلجَؤُهُم لِحِفظِ دينِهِم',en:'Their refuge to protect their faith'} },
      { tool:{ar:'٣٠٩ سِنين',en:'309 years'}, job:{ar:'مُدّةُ نَومِهِم بِحِفظِ الله',en:'Their sleep under Allah\'s protection'} },
      { tool:{ar:'الكَلب',en:'The dog'}, job:{ar:'حَرَسَهُم على بابِ الكَهف',en:'Guarded them at the cave\'s entrance'} },
    ] },
  reflection:{
    ayah:'﴿إِنَّهُمْ فِتْيَةٌ آمَنُوا بِرَبِّهِمْ وَزِدْنَاهُمْ هُدًى ۝ وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا فَقَالُوا رَبُّنَا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ﴾',
    ref:{ ar:'سورة الكَهف · ١٣–١٤', en:'Surah Al-Kahf · 13–14' },
    explain:{
      ar:'تَأمَّل كَلِمةَ ﴿<b>ورَبَطنا على قُلوبِهِم</b>﴾ — أيْ قَوّى اللهُ قُلوبَهُم وثَبَّتَها كَما يُربَطُ الشَّيءُ لِئَلّا يَتَحَرَّك. فالثَّباتُ هَدِيّةٌ مِنَ اللهِ يُعطيها مَن صَدَقَ في إيمانِه. ولَمّا «قاموا» وقالوا كَلِمةَ الحَقِّ شُجعاناً، زادَهُمُ اللهُ هُدًى وقُوّة. وهذِهِ سُنّةٌ ثابِتة: مَن خَطا نَحوَ اللهِ خُطوة، ثَبَّتَهُ اللهُ وزادَهُ هُدًى. فَاطلُب مِن رَبِّكَ دائِماً: «يا مُقَلِّبَ القُلوبِ ثَبِّت قَلبي على دينِك».',
      en:'Reflect on the words ﴾<b>and We bound their hearts</b>﴿ — Allah strengthened and steadied their hearts, as a thing is tied so it won\'t move. Steadfastness is a gift Allah gives to whoever is truthful in his faith. When they "stood up" and bravely spoke the word of truth, Allah increased them in guidance and strength. This is a constant way: whoever steps toward Allah, Allah makes him firm and adds guidance. So always ask your Lord: "O Turner of hearts, keep my heart firm on Your religion."' } },
  card:{ name:{ar:'فِتيةُ الكَهف',en:'The Youth of the Cave'}, meaning:{ar:'شَبابٌ آمَنوا بِرَبِّهِم وتَرَكوا كُلَّ شَيءٍ لِيَحفَظوا دينَهُم، فَحَفِظَهُمُ اللهُ وخَلَّدَ ذِكرَهُم — والشَّبابُ أبطالُ الإيمان',en:'Young men who believed and left everything to protect their faith, so Allah protected them and immortalized them — youth are the heroes of faith'} },
  proof:{ ar:'دينِي أغلى مِن كُلِّ شَيء، وأبتَعِدُ عنِ السّوءِ لِأحفَظَه', en:'My faith is more precious than everything, and I step away from evil to protect it' },
  dua:{ ar:'رَبَّنا آتِنا مِن لَدُنكَ رَحمةً وهَيِّئ لَنا مِن أمرِنا رَشَداً', en:'Our Lord, grant us mercy from Yourself and guide us rightly in our affair' },
  mission:{ ar:'🕳️ مُهِمّةُ البُطولة: اقرَأ هذا الأُسبوعَ أوَّلَ عَشرِ آياتٍ مِن سورةِ الكَهف (تَحفَظُكَ مِنَ الفِتَن كَما في الحَديث)، وإن كانَ مَعَكَ صَديقٌ يَدعوكَ لِخَطَأ، تَذَكَّر فِتيةَ الكَهفِ وابتَعِد بِأدَب.', en:'🕳️ Hero Mission: This week, read the first ten verses of Surah Al-Kahf (they protect from trials, as in the hadith), and if a friend invites you to do wrong, remember the youth of the cave and step away politely.' },
  badge:{ icon:'🐕', color:'#2C7A6B', title:{ ar:'فَتى الكَهف', en:'Youth of the Cave' } }
},

/* ───────────── 3 · Pharaoh's Sorcerers ───────────── */
{
  id:'sahara', num:3, icon:'🪄', emoji:'🙇', color:'#8E44AD',
  title:{ ar:'سَحَرةُ فِرعَون — مِن أعداءٍ إلى شُهَداء', en:'Pharaoh\'s Sorcerers — From Enemies to Martyrs' },
  narration:{
    ar:'أعجَبُ تَحَوُّلٍ في التّاريخ! 🪄 جَمَعَ فِرعَونُ أمهَرَ سَحَرةِ مَملَكَتِهِ لِيَتَحَدّوا موسى عليه السلام أمامَ النّاسِ جَميعاً. جاؤوا طامِعينَ في المالِ والجاه، وقالوا لِفِرعَون: ﴿أئِنَّ لَنا لَأجراً إن كُنّا نَحنُ الغالِبين؟﴾ فَوَعَدَهُمُ المالَ والقُربَ مِنه. ألقَوا حِبالَهُم وعِصِيَّهُم فَخُيِّلَ لِلنّاسِ أنها ثَعابينُ تَسعى. ثُمَّ ألقى موسى عَصاهُ بِأمرِ الله، فإذا هي ثُعبانٌ حَقيقيٌّ ضَخمٌ ابتَلَعَ كُلَّ سِحرِهِم! وهُنا حَدَثَ المَوقِفُ العَظيم: السَّحَرةُ — وهُم أعلَمُ النّاسِ بِالسِّحرِ وحُدودِه — عَرَفوا فَوراً أنَّ هذا <b>لَيسَ سِحراً بَل آيةٌ مِنَ الله</b>! فَخَرّوا ساجِدينَ في لَحظةٍ واحِدةٍ وقالوا: ﴿<b>آمَنّا بِرَبِّ العالَمين، رَبِّ موسى وهارون</b>﴾. غَضِبَ فِرعَونُ غَضَباً شَديداً وهَدَّدَهُم بِأبشَعِ تَهديد: ﴿لَأُقَطِّعَنَّ أيدِيَكُم وأرجُلَكُم مِن خِلافٍ ثُمَّ لَأُصَلِّبَنَّكُم﴾! فَهَل خافوا ورَجَعوا؟ أبَداً! قالوا بِقُلوبٍ كَالجِبال: ﴿<b>لَن نُؤثِرَكَ على ما جاءَنا مِنَ البَيِّنات</b>﴾ — لَن نُفَضِّلَكَ على الحَقِّ الذي عَرَفناه!',
    en:'The most astonishing transformation in history! 🪄 Pharaoh gathered the most skilled sorcerers of his kingdom to challenge Musa (peace be upon him) before all the people. They came greedy for money and status, asking Pharaoh: ﴾Will there be a reward for us if we are the winners?﴿ He promised them wealth and closeness to him. They cast their ropes and staffs, and it was made to seem to people they were slithering snakes. Then Musa cast his staff by Allah\'s command, and it became a real, huge serpent that swallowed all their magic! Here came the great moment: the sorcerers — the most knowledgeable of people about magic and its limits — instantly knew this was <b>not magic but a sign from Allah</b>! They fell in prostration in a single moment, saying: ﴾<b>We believe in the Lord of the worlds, the Lord of Musa and Harun</b>﴿. Pharaoh raged and threatened them with the ugliest threat: ﴾I will surely cut off your hands and feet on opposite sides, then crucify you all!﴿ Did they fear and turn back? Never! They said, with hearts like mountains: ﴾<b>We will never prefer you over the clear signs that have come to us</b>﴿!' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ يَتَحَوَّلُ السَّحَرةُ مِن أعداءٍ لِموسى إلى مُؤمِنينَ في لَحظة؟» 🤔', en:'A question crosses your mind: "How did the sorcerers turn from Musa\'s enemies into believers in a moment?" 🤔' },
  logic:{
    ar:'لِأنَّ القَلبَ الذي يَبحَثُ عنِ الحَقِّ بِصِدق، إذا رَآهُ واضِحاً <b>تَبِعَهُ فَوراً</b> مَهما كانَ الثَّمَن! السَّحَرةُ جاؤوا في الصَّباحِ يَطلُبونَ مالَ فِرعَون، وأمسَوا شُهَداءَ يَطلُبونَ جَنّةَ الله. ما الذي تَغَيَّر؟ عَرَفوا الحَقّ، فَلَم يُكابِروا. وهذا دَرسٌ عَظيم: <b>الشُّجاعةُ الحَقيقيّةُ أن تَتبَعَ الحَقَّ فَورَ أن تَعرِفَه</b>، ولو خالَفَ ما كُنتَ علَيهِ بِالأمس. ولاحِظ كَيفَ كانَ إيمانُهُم سَريعاً وقَوِيّاً: في ساعةٍ واحِدةٍ صارَ تَهديدُ القَتلِ والتَّعذيبِ لا يُساوي عِندَهُم شَيئاً أمامَ حَلاوةِ الإيمان! قالوا لِفِرعَون كَلِمةً يَجِبُ أن نَحفَظَها: ﴿واللهُ خَيرٌ وأبقى﴾ — ما عِندَ اللهِ خَيرٌ مِن دُنياك، وأبقى مِن مُلكِكَ الزّائِل. هؤلاءِ الذينَ كانوا يَخدِمونَ الباطِلَ بِالأمس، صاروا اليومَ أئِمّةً في الثَّبات. فَلا تَيأَس مِن أحَدٍ، وإذا عَرَفتَ الحَقَّ فَكُن شُجاعاً مِثلَهُم.',
    en:'Because a heart that sincerely seeks the truth, when it sees it clearly, <b>follows it at once</b> whatever the price! The sorcerers came in the morning seeking Pharaoh\'s money and ended the day as martyrs seeking Allah\'s Paradise. What changed? They recognized the truth and didn\'t stubbornly resist. This is a great lesson: <b>true courage is to follow the truth the moment you know it</b>, even if it contradicts what you were on yesterday. Notice how quick and strong their faith was: in a single hour, threats of killing and torture meant nothing to them next to the sweetness of faith! They said to Pharaoh words we should memorize: ﴾And Allah is better and more lasting﴿ — what is with Allah is better than your world and more lasting than your fading kingdom. These people who served falsehood yesterday became, today, leaders in steadfastness. So never despair of anyone, and when you know the truth, be brave like them.' },
  myth:{ claim:{ ar:'«مَن عاشَ على الباطِلِ لا يُمكِنُ أن يَتَغَيَّرَ ويَصيرَ بَطَلاً!»', en:'"Whoever lived on falsehood can never change and become a hero!"' },
         bust:{ ar:'سَحَرةُ فِرعَونَ كانوا أعداءَ موسى في الصَّباح، وأمسَوا شُهَداءَ ثابِتينَ لا يَخافونَ القَتل. القَلبُ الصّادِقُ يَتبَعُ الحَقَّ فَورَ أن يَراه.', en:'Pharaoh\'s sorcerers were Musa\'s enemies in the morning and ended the day as steadfast martyrs fearing no death. A sincere heart follows the truth the moment it sees it.' } },
  match:{
    title:{ ar:'صِل كُلَّ مَوقِفٍ بِصاحِبِه', en:'Match each stand to its owner' },
    pairs:[
      { tool:{ar:'السَّحَرةُ في الصَّباح',en:'The sorcerers in the morning'}, job:{ar:'يَطلُبونَ مالَ فِرعَون',en:'Seeking Pharaoh\'s money'} },
      { tool:{ar:'السَّحَرةُ في المَساء',en:'The sorcerers by evening'}, job:{ar:'شُهَداءُ يَطلُبونَ الجَنّة',en:'Martyrs seeking Paradise'} },
      { tool:{ar:'تَهديدُ فِرعَون',en:'Pharaoh\'s threat'}, job:{ar:'التَّقطيعُ والصَّلب',en:'Cutting off limbs and crucifixion'} },
      { tool:{ar:'جَوابُ السَّحَرة',en:'The sorcerers\' reply'}, job:{ar:'لَن نُؤثِرَكَ على الحَقّ',en:'We\'ll never prefer you over the truth'} },
    ] },
  reflection:{
    ayah:'﴿قَالُوا لَن نُّؤْثِرَكَ عَلَىٰ مَا جَاءَنَا مِنَ الْبَيِّنَاتِ وَالَّذِي فَطَرَنَا ۖ فَاقْضِ مَا أَنتَ قَاضٍ﴾',
    ref:{ ar:'سورة طه · ٧٢', en:'Surah Ta-Ha · 72' },
    explain:{
      ar:'انظُر إلى قُوّةِ هذِهِ الكَلِمات: «اقضِ ما أنتَ قاضٍ» — أيْ: افعَل ما شِئتَ يا فِرعَون، فَلَن نَترُكَ إيمانَنا! قَبلَ ساعاتٍ كانوا يَرتَجِفونَ طَمَعاً في عَطاءِ فِرعَون، والآنَ لا يُبالونَ بِأشَدِّ عُقوباتِه. ما الذي يُعطي القَلبَ هذِهِ القُوّة؟ <b>اليَقينُ بِاللهِ والآخِرة</b>. مَن عَرَفَ أنَّ هذِهِ الدُّنيا قَصيرةٌ وأنَّ الجَنّةَ خالِدة، هانَ علَيهِ كُلُّ تَهديد. هذا هو الثَّباتُ: لا يَأتي مِن قُوّةِ الجِسم، بَل مِن قُوّةِ اليَقينِ في القَلب.',
      en:'Look at the strength of these words: "So decree whatever you will to decree" — meaning: do whatever you want, Pharaoh, we will not abandon our faith! Hours earlier they were trembling in greed for Pharaoh\'s gift; now they don\'t care about his harshest punishment. What gives a heart this strength? <b>Certainty in Allah and the Hereafter</b>. Whoever knows this world is short and Paradise is eternal finds every threat trivial. This is steadfastness: it doesn\'t come from bodily strength but from the strength of certainty in the heart.' } },
  card:{ name:{ar:'سَحَرةُ فِرعَون',en:'Pharaoh\'s Sorcerers'}, meaning:{ar:'أعداءٌ لِموسى تَحَوَّلوا في لَحظةٍ إلى مُؤمِنينَ ثابِتينَ لا يَخافونَ تَهديدَ القَتل — لِأنَّ القَلبَ الصّادِقَ يَتبَعُ الحَقَّ فَوراً',en:'Enemies of Musa who turned in a moment into steadfast believers fearing no threat of death — because a sincere heart follows the truth at once'} },
  proof:{ ar:'الشُّجاعةُ أن أتبَعَ الحَقَّ فَورَ أن أعرِفَه، مَهما كانَ الثَّمَن', en:'Courage is to follow the truth the moment I know it, whatever the price' },
  dua:{ ar:'رَبَّنا أفرِغ علَينا صَبراً وتَوَفَّنا مُسلِمين', en:'Our Lord, pour patience upon us and let us die as Muslims' },
  mission:{ ar:'🪄 مُهِمّةُ البُطولة: هل تَعَلَّمتَ اليومَ أنَّ شَيئاً تَفعَلُهُ خَطَأ؟ كُن مِثلَ السَّحَرة: اترُكهُ فَوراً وارجِع لِلصَّوابِ بِشَجاعة، ولا تُكابِر. الرُّجوعُ إلى الحَقِّ بُطولة.', en:'🪄 Hero Mission: Did you learn today that something you do is wrong? Be like the sorcerers: drop it at once and return to what\'s right bravely, without stubbornness. Returning to the truth is heroism.' },
  badge:{ icon:'🙇', color:'#8E44AD', title:{ ar:'شُجاعُ الحَقّ', en:'Brave for the Truth' } }
},

/* ───────────── 4 · Asiya, Pharaoh's Wife ───────────── */
{
  id:'asiya', num:4, icon:'👑', emoji:'🏯', color:'#B0578D',
  title:{ ar:'آسِيَة — مُؤمِنةٌ في قَصرِ الطّاغِية', en:'Asiya — A Believer in the Tyrant\'s Palace' },
  narration:{
    ar:'بَطَلَتُنا اليومَ امرَأةٌ عَظيمةٌ جَعَلَها اللهُ مَثَلاً لِكُلِّ المُؤمِنين: <b>آسِيَةُ زَوجةُ فِرعَون</b>! 🏯 تَخَيَّل: تَعيشُ في أفخَمِ قَصرٍ على الأرض، زَوجُها أقوى مَلِكٍ في زَمانِه، عِندَها كُلُّ ما تَتَمَنّاهُ مِن مالٍ وخَدَمٍ وذَهَب. لكنَّ فِرعَونَ كانَ طاغِيةً يَقولُ لِلنّاسِ: «أنا رَبُّكُمُ الأعلى»! ومَعَ ذلكَ آمَنَت آسِيَةُ بِاللهِ الواحِدِ في السِّرّ، لِأنَّ قَلبَها عَرَفَ الحَقّ. ولَمّا عَلِمَ فِرعَونُ بِإيمانِها، أرادَ أن يُرجِعَها بِالقُوّة، فَعَذَّبَها عَذاباً شَديداً. فَهَل تَخَلَّت عن إيمانِها لِتَحتَفِظَ بِالقَصرِ والمُلك؟ أبَداً! بَل رَفَعَت يَدَيها إلى السَّماءِ وهي تُعَذَّبُ ودَعَت بِأجمَلِ دُعاء: ﴿<b>رَبِّ ابنِ لي عِندَكَ بَيتاً في الجَنّة</b>، ونَجِّني مِن فِرعَونَ وعَمَلِه﴾. لاحِظ: لم تَطلُب أن يَرفَعَ اللهُ عنها العَذاب، بَل طَلَبَت <b>بَيتاً في الجَنّة</b>! فَأراها اللهُ بَيتَها في الجَنّةِ وهي حَيّةٌ فَابتَسَمَت، وقَبَضَ روحَها وهي راضِيةٌ سَعيدة. وصارَت إحدى أكمَلِ النِّساءِ في التّاريخ.',
    en:'Today\'s hero is a great woman whom Allah made an example for all believers: <b>Asiya, the wife of Pharaoh</b>! 🏯 Imagine: living in the most luxurious palace on earth, her husband the mightiest king of his time, possessing everything she could wish of money, servants, and gold. But Pharaoh was a tyrant who told people: "I am your lord, the most high"! Yet Asiya believed secretly in the One God, because her heart knew the truth. When Pharaoh learned of her faith, he wanted to force her back, and tortured her severely. Did she abandon her faith to keep the palace and kingdom? Never! She raised her hands to the sky while being tortured and made the most beautiful du\'a: ﴾<b>My Lord, build for me a house with You in Paradise</b>, and save me from Pharaoh and his deeds﴿. Notice: she didn\'t ask Allah to lift the torture, but asked for <b>a house in Paradise</b>! So Allah showed her her house in Paradise while she was still alive, and she smiled, and He took her soul while she was content and happy. She became one of the most perfect women in history.' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ تَترُكُ مَلِكةٌ قَصرَها ومُلكَها مِن أجلِ الإيمان؟» 🤔', en:'A question crosses your mind: "How could a queen give up her palace and kingdom for faith?" 🤔' },
  logic:{
    ar:'لِأنَّ آسِيَةَ كانَت تَرى ما لا يَراهُ كَثيرٌ مِنَ النّاس: أنَّ <b>قَصرَ الدُّنيا مَهما كَبُرَ زائِلٌ، وبَيتَ الجَنّةِ باقٍ</b>. ما فائِدةُ أفخَمِ قَصرٍ إذا كانَ صاحِبُهُ سَيَتركُهُ ويَموت؟ وما قيمةُ بَيتٍ صَغيرٍ في الجَنّةِ يَدومُ إلى الأبَدِ بِلا حُزنٍ ولا مَوت؟ آسِيَةُ اختارَت الباقي على الفاني، فَكانَت أذكى مِن كُلِّ مَن حَولَها. ودَرسُها العَظيمُ لَنا: <b>الإيمانُ لا يَحتاجُ ظُروفاً سَهلة</b>. بَعضُ النّاسِ يَقول: «سَأتَدَيَّنُ حينَ تَتَحَسَّنُ حَياتي» أو «البيئةُ حَولي صَعبة». وآسِيَةُ كانَت في أصعَبِ بيئةٍ مُمكِنة — بَيتُ فِرعَونَ نَفسِه — ومَعَ ذلكَ كانَ قَلبُها أنقى قَلب! فَلا يَمنَعُكَ مَكانٌ ولا أُناسٌ مِنَ التَّمَسُّكِ بِدينِك. وانظُر إلى دُعائِها الذَّكِيّ: قَدَّمَتِ «الجارَ» قَبلَ «الدّار» — طَلَبَت القُربَ مِنَ اللهِ «عِندَك» قَبلَ أن تَطلُبَ البَيت. هذا قَلبُ بَطَلةٍ حَقيقيّة: يُريدُ اللهَ أكثَرَ مِن كُلِّ شَيء.',
    en:'Because Asiya saw what many people don\'t: that <b>the palace of this world, however grand, fades, while the house of Paradise endures</b>. What good is the finest palace if its owner will leave it and die? And what is the worth of a small house in Paradise that lasts forever with no sadness or death? Asiya chose the lasting over the fleeting, so she was wiser than everyone around her. Her great lesson for us: <b>faith doesn\'t need easy circumstances</b>. Some people say: "I\'ll become religious when my life improves" or "my environment is hard." Asiya was in the hardest possible environment — Pharaoh\'s own house — yet her heart was the purest! So let no place or people stop you from holding to your faith. And look at her clever du\'a: she put "the neighbor" before "the house" — she asked for nearness to Allah "with You" before asking for the house. That\'s the heart of a true hero: wanting Allah more than everything.' },
  myth:{ claim:{ ar:'«لا أستَطيعُ التَّمَسُّكَ بِديني لِأنَّ مَن حَولي والظُّروفَ صَعبة!»', en:'"I can\'t hold to my faith because the people and circumstances around me are hard!"' },
         bust:{ ar:'آسِيَةُ آمَنَت في بَيتِ فِرعَونَ نَفسِه — أصعَبِ بيئةٍ على الأرض — وثَبَتَت حتّى المَوت. الإيمانُ لا يَحتاجُ ظُروفاً سَهلة، بَل قَلباً صادِقاً.', en:'Asiya believed in Pharaoh\'s own house — the hardest environment on earth — and held firm until death. Faith doesn\'t need easy circumstances, just a sincere heart.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَعناه', en:'Match each thing to its meaning' },
    pairs:[
      { tool:{ar:'آسِيَة',en:'Asiya'}, job:{ar:'مُؤمِنةٌ ثَبَتَت في قَصرِ الطّاغِية',en:'A believer firm in the tyrant\'s palace'} },
      { tool:{ar:'قَصرُ فِرعَون',en:'Pharaoh\'s palace'}, job:{ar:'مُلكٌ زائِلٌ تَرَكَتهُ لِلجَنّة',en:'A fading kingdom she left for Paradise'} },
      { tool:{ar:'«بَيتاً في الجَنّة»',en:'"A house in Paradise"'}, job:{ar:'ما طَلَبَتهُ وهي تُعَذَّب',en:'What she asked for while tortured'} },
      { tool:{ar:'«عِندَك» قَبلَ «بَيتاً»',en:'"With You" before "a house"'}, job:{ar:'أرادَتِ القُربَ مِنَ اللهِ أوَّلاً',en:'She wanted nearness to Allah first'} },
    ] },
  reflection:{
    ayah:'﴿وَضَرَبَ اللَّهُ مَثَلًا لِّلَّذِينَ آمَنُوا امْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ﴾',
    ref:{ ar:'سورة التَّحريم · ١١', en:'Surah At-Tahrim · 11' },
    explain:{
      ar:'جَعَلَ اللهُ آسِيَةَ <b>مَثَلاً لِكُلِّ المُؤمِنينَ</b> — رِجالاً ونِساءً — في قُوّةِ الإيمانِ والثَّبات. ومَعَ أنها كانَت أضعَفَ النّاسِ ظاهِراً (امرَأةٌ تَحتَ سُلطانِ أعتى طاغِية)، إلّا أنها كانَت أقوى النّاسِ قَلباً. وهذا يُعَلِّمُنا أنَّ القُوّةَ الحَقيقيّةَ لَيسَت في السُّلطانِ والمال، بَل في الإيمانِ الذي لا يَنكَسِر. فَكُن كَآسِيَةَ: اجعَل هَمَّكَ الأكبَرَ بَيتاً في الجَنّةِ قُربَ رَبِّك، ولا تَبِع آخِرَتَكَ بِدُنيا أحَد.',
      en:'Allah made Asiya <b>an example for all believers</b> — men and women — in strength of faith and steadfastness. Although she was outwardly the weakest of people (a woman under the power of the fiercest tyrant), she was the strongest of people in heart. This teaches us that true strength isn\'t in power and wealth, but in faith that doesn\'t break. So be like Asiya: make your greatest aim a house in Paradise near your Lord, and never sell your Hereafter for anyone\'s worldly life.' } },
  card:{ name:{ar:'آسِيَةُ بِنتُ مُزاحِم',en:'Asiya bint Muzahim'}, meaning:{ar:'زَوجةُ فِرعَونَ التي آمَنَت وثَبَتَت تَحتَ التَّعذيب، وطَلَبَت بَيتاً في الجَنّةِ بَدَلَ قَصرِ الدُّنيا — مَثَلٌ لِكُلِّ مُؤمِن',en:'Pharaoh\'s wife who believed and held firm under torture, asking for a house in Paradise instead of the worldly palace — an example for every believer'} },
  proof:{ ar:'الإيمانُ لا يَحتاجُ ظُروفاً سَهلة، بَل قَلباً صادِقاً يُريدُ اللهَ أوَّلاً', en:'Faith doesn\'t need easy circumstances, just a sincere heart that wants Allah first' },
  dua:{ ar:'رَبِّ ابنِ لي عِندَكَ بَيتاً في الجَنّة، ونَجِّني مِن كُلِّ ظالِمٍ وعَمَلِه', en:'My Lord, build for me a house with You in Paradise, and save me from every oppressor and his deeds' },
  mission:{ ar:'👑 مُهِمّةُ البُطولة: احفَظ دُعاءَ آسِيَةَ «رَبِّ ابنِ لي عِندَكَ بَيتاً في الجَنّة»، وادعُ بِهِ اللَّيلةَ بِقَلبٍ حاضِر — واجعَل بَيتَ الجَنّةِ حُلمَكَ الأكبَر.', en:'👑 Hero Mission: Memorize Asiya\'s du\'a "My Lord, build for me a house with You in Paradise," and pray it tonight with a present heart — make the house of Paradise your biggest dream.' },
  badge:{ icon:'🏯', color:'#B0578D', title:{ ar:'صاحِبةُ البَيتِ في الجَنّة', en:'Owner of the House in Paradise' } }
},

/* ───────────── 5 · Ibrahim & the Fire ───────────── */
{
  id:'ibrahim', num:5, icon:'🪵', emoji:'🌿', color:'#2E8B57',
  title:{ ar:'إبراهيمُ في النّار — حَسبُنا الله', en:'Ibrahim & the Fire — Allah Is Sufficient' },
  narration:{
    ar:'بَطَلُنا اليومَ نَبِيٌّ عَظيمٌ هو <b>إبراهيمُ خَليلُ الرَّحمن</b> عليه السلام! 🌿 عاشَ في قَومٍ يَعبُدونَ أصناماً مِن حِجارة، وكانَ مَلِكُهُمُ الجَبّارُ «النَّمرود» يَدَّعي الرُّبوبِيّة. وقَفَ إبراهيمُ وَحدَهُ — شابّاً — في وَجهِ قَومِهِ كُلِّهِم، وقال: لِماذا تَعبُدونَ حِجارةً لا تَسمَعُ ولا تَنفَع؟ ثُمَّ فَعَلَ شَيئاً جَريئاً: كَسَّرَ أصنامَهُم كُلَّها إلّا الكَبيرَ، لِيُثبِتَ لَهُم أنها عاجِزةٌ لا تَدفَعُ عن نَفسِها. فَغَضِبوا غَضَباً شَديداً وقَرَّروا أبشَعَ عُقوبة: ﴿<b>حَرِّقوهُ وانصُروا آلِهَتَكُم</b>﴾! جَمَعوا حَطَباً عَظيماً حتّى صارَتِ النّارُ جَبَلاً مُشتَعِلاً، لم يَستَطِع أحَدٌ الاقتِرابَ مِنها مِن شِدّةِ حَرِّها، فَرَمَوهُ فيها بِمَنجَنيق. وفي تِلكَ اللَّحظةِ الرَّهيبة، ماذا قالَ إبراهيم؟ كَلِمةً صارَت سِلاحَ كُلِّ مُؤمِنٍ بَعدَه: «<b>حَسبُنا اللهُ ونِعمَ الوَكيل</b>» — يَكفينا اللهُ ونِعمَ المَوكولُ إلَيهِ الأمر! فَجاءَ الأمرُ مِنَ السَّماءِ فَوراً: ﴿<b>يا نارُ كوني بَرداً وسَلاماً على إبراهيم</b>﴾ — فَصارَتِ النّارُ المُشتَعِلةُ بَرداً وأماناً، وخَرَجَ سالِماً لم تَمَسَّهُ بِأذًى!',
    en:'Today\'s hero is a great prophet, <b>Ibrahim, the close friend of the Most Merciful</b> (peace be upon him)! 🌿 He lived among a people who worshipped idols of stone, and their tyrant king "Nimrod" claimed lordship. Ibrahim stood alone — as a young man — against his entire people, saying: why do you worship stones that neither hear nor benefit? Then he did something bold: he smashed all their idols except the biggest, to prove to them they were powerless and couldn\'t even defend themselves. They raged furiously and decided on the ugliest punishment: ﴾<b>Burn him and support your gods</b>﴿! They gathered so much firewood that the fire became a blazing mountain; no one could approach it from its intense heat, so they hurled him in with a catapult. In that terrifying moment, what did Ibrahim say? Words that became the weapon of every believer after him: "<b>Allah is sufficient for us, and what an excellent Trustee</b>"! The command came from heaven at once: ﴾<b>O fire, be coolness and safety upon Ibrahim</b>﴿ — and the blazing fire became cool and safe, and he came out unharmed, untouched by any injury!' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ يَقِفُ شابٌّ واحِدٌ في وَجهِ قَومِهِ كُلِّهِم بِلا خَوف؟» 🤔', en:'A question crosses your mind: "How does one young man stand against his entire people without fear?" 🤔' },
  logic:{
    ar:'لِأنَّ إبراهيمَ كانَ يَعلَمُ حَقيقةً يَنساها الخائِفون: <b>أنَّ مَن مَعَهُ اللهُ لا يَغلِبُهُ أحَد</b>! فَالنّاسُ مَهما كَثُروا، واللهُ مَعَكَ، فَأنتَ الأقوى. وانتَبِه لِأعظَمِ دَرسٍ في القِصّة: الأسبابُ كُلُّها كانَت ضِدَّ إبراهيم — نارٌ هائِلة، وقَومٌ كَثيرون، وهو وَحيد. ومَعَ ذلكَ نَجا. لِماذا؟ لِأنَّ النّارَ لا تُحرِقُ بِطَبعِها، بَل <b>بِأمرِ الله</b>! النّارُ تُحرِقُ لِأنَّ اللهَ أمَرَها أن تُحرِق، فإذا أمَرَها أن تَبرُدَ بَرَدَت. كُلُّ شَيءٍ في الكَونِ جُندِيٌّ يُطيعُ خالِقَه. فَحينَ تَتَوَكَّلُ على اللهِ حَقّاً، فَأنتَ تَتَوَكَّلُ على مَن يَملِكُ كُلَّ الأسباب. وكَلِمةُ «حَسبُنا اللهُ ونِعمَ الوَكيل» هي مِفتاحُ الثَّبات: قُلها عِندَ الخَوفِ، عِندَ الامتِحان، عِندَ مُواجَهةِ الظُّلم — فَهي تَملأُ القَلبَ قُوّةً وطُمَأنينة. إبراهيمُ عَلَّمَنا أنَّ البَطَلَ الحَقيقيَّ لَيسَ مَن لا يُخطِئُ الخَوفُ قَلبَه، بَل مَن يَتَوَكَّلُ على اللهِ فَيَتَحَوَّلُ خَوفُهُ إلى يَقين.',
    en:'Because Ibrahim knew a truth the fearful forget: <b>whoever has Allah with him, no one can defeat</b>! However many the people, if Allah is with you, you are the stronger. And note the greatest lesson in the story: all the means were against Ibrahim — a raging fire, a numerous people, and he alone. Yet he was saved. Why? Because fire doesn\'t burn by its own nature, but <b>by Allah\'s command</b>! Fire burns because Allah commanded it to burn; when He commands it to cool, it cools. Everything in the universe is a soldier obeying its Creator. So when you truly rely on Allah, you rely on the One who owns all the means. And the words "Allah is sufficient for us, and what an excellent Trustee" are the key to steadfastness: say them when afraid, at an exam, when facing oppression — they fill the heart with strength and peace. Ibrahim taught us that the true hero isn\'t one whose heart fear never touches, but one who relies on Allah so his fear turns into certainty.' },
  myth:{ claim:{ ar:'«الواحِدُ لا يَستَطيعُ شَيئاً أمامَ الكَثيرين!»', en:'"One person can do nothing against the many!"' },
         bust:{ ar:'إبراهيمُ وَقَفَ وَحدَهُ أمامَ قَومِهِ ونارِهِم، وقال «حَسبُنا اللهُ ونِعمَ الوَكيل»، فَنَجّاهُ الله. مَن كانَ اللهُ مَعَهُ فَهو الأقوى ولو كانَ وَحدَه.', en:'Ibrahim stood alone against his people and their fire, said "Allah is sufficient for us," and Allah saved him. Whoever has Allah with him is the strongest, even alone.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'إبراهيم',en:'Ibrahim'}, job:{ar:'وَقَفَ وَحدَهُ يَدعو لِلتَّوحيد',en:'Stood alone calling to monotheism'} },
      { tool:{ar:'«حَسبُنا اللهُ ونِعمَ الوَكيل»',en:'"Allah is sufficient for us"'}, job:{ar:'قالَها وهو يُلقى في النّار',en:'He said it as he was thrown in the fire'} },
      { tool:{ar:'«كوني بَرداً وسَلاماً»',en:'"Be coolness and safety"'}, job:{ar:'أمرُ اللهِ لِلنّار',en:'Allah\'s command to the fire'} },
      { tool:{ar:'النّار',en:'The fire'}, job:{ar:'جُندِيٌّ يُطيعُ أمرَ خالِقِه',en:'A soldier obeying its Creator\'s command'} },
    ] },
  reflection:{
    ayah:'﴿قُلْنَا يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَىٰ إِبْرَاهِيمَ﴾',
    ref:{ ar:'سورة الأنبِياء · ٦٩', en:'Surah Al-Anbiya · 69' },
    explain:{
      ar:'كَلِمةٌ واحِدةٌ مِنَ اللهِ غَيَّرَت طَبيعةَ النّار! لاحِظ أنه قال «بَرداً <b>وسَلاماً</b>» — لِأنَّ البَردَ الشَّديدَ يُؤذي أيضاً، فَأمَرَها أن تَكونَ بَرداً مُسالِماً لا يَضُرّ. هذا يُعَلِّمُنا أنَّ الأسبابَ كُلَّها بِيَدِ الله: النّارُ لا تُحرِقُ إلّا بِإذنِه، والماءُ لا يُغرِقُ إلّا بِإذنِه. فَلا تَخَف مِنَ المَخلوقاتِ، بَل خَف مِن خالِقِها وتَوَكَّل علَيه. ومَن جَعَلَ اللهَ وَكيلَهُ، كَفاهُ ووَقاهُ مِن حَيثُ لا يَحتَسِب.',
      en:'One word from Allah changed the nature of fire! Notice He said "coolness <b>and safety</b>" — because intense cold also harms, so He commanded it to be a peaceful coolness that doesn\'t hurt. This teaches us that all means are in Allah\'s hand: fire only burns by His leave, water only drowns by His leave. So don\'t fear creatures; fear their Creator and rely on Him. Whoever makes Allah his Trustee, He suffices and protects him from where he doesn\'t expect.' } },
  card:{ name:{ar:'حَسبُنا اللهُ ونِعمَ الوَكيل',en:'Allah Is Sufficient for Us'}, meaning:{ar:'كَلِمةُ التَّوَكُّلِ التي قالَها إبراهيمُ في النّارِ فَنَجّاهُ الله — سِلاحُ كُلِّ مُؤمِنٍ خائِفٍ يُحَوِّلُ الخَوفَ إلى يَقين',en:'The words of trust Ibrahim said in the fire, by which Allah saved him — the weapon of every fearful believer, turning fear into certainty'} },
  proof:{ ar:'مَن كانَ اللهُ مَعَهُ فَهو الأقوى، ولو وَقَفَ وَحدَهُ أمامَ الجَميع', en:'Whoever has Allah with him is the strongest, even standing alone against everyone' },
  dua:{ ar:'حَسبُنا اللهُ ونِعمَ الوَكيل، حَسبِيَ اللهُ لا إلهَ إلّا هو علَيهِ تَوَكَّلت', en:'Allah is sufficient for us, what an excellent Trustee; Allah suffices me, there is no god but He, in Him I trust' },
  mission:{ ar:'🪵 مُهِمّةُ البُطولة: في أوَّلِ مَوقِفٍ يُخيفُكَ هذا الأُسبوعَ (امتِحان، طَبيب، ظَلام)، قُل بِقَلبِك «حَسبُنا اللهُ ونِعمَ الوَكيل» ثَلاثاً — ولاحِظ كَيفَ يَهدَأُ قَلبُكَ كَنارِ إبراهيم.', en:'🪵 Hero Mission: At the first thing that scares you this week (an exam, the doctor, the dark), say in your heart "Allah is sufficient for us, what an excellent Trustee" three times — and notice how your heart calms like Ibrahim\'s fire.' },
  badge:{ icon:'🌿', color:'#2E8B57', title:{ ar:'المُتَوَكِّلُ على الله', en:'The One Who Trusts Allah' } }
},

/* ───────────── 6 · Bilal — Ahad, Ahad ───────────── */
{
  id:'bilal', num:6, icon:'⛓️', emoji:'☀️', color:'#C26A1E',
  title:{ ar:'بِلالٌ — أحَدٌ أحَد', en:'Bilal — Ahad, Ahad (One, One)' },
  narration:{
    ar:'بَطَلُنا اليومَ صَوتُ الإسلامِ الأوَّل: <b>بِلالُ بنُ رَباح</b> رضي الله عنه! ☀️ كانَ عَبداً في مَكّة، ضَعيفاً فَقيراً لا يَملِكُ مِنَ الدُّنيا شَيئاً، مَملوكاً لِسَيِّدٍ قاسٍ مِن كُفّارِ قُرَيش. ولَمّا سَمِعَ بِالإسلامِ آمَنَ بِهِ قَلبُهُ فَوراً، لِأنه عَرَفَ أنَّ اللهَ خَلَقَ النّاسَ سَواءً، لا فَرقَ بَينَ سَيِّدٍ وعَبدٍ إلّا بِالتَّقوى. فَلَمّا عَلِمَ سَيِّدُهُ، غَضِبَ غَضَباً شَديداً وأرادَ أن يُرجِعَهُ عنِ الإسلامِ بِالتَّعذيب. كانَ يُخرِجُهُ في شِدّةِ حَرِّ الظَّهيرةِ إلى الرَّملِ المُحرِقِ في الصَّحراء، ويُلقيهِ على ظَهرِهِ، ويَضَعُ على صَدرِهِ <b>صَخرةً عَظيمة</b>، ويَقول: لَن أترُكَكَ حتّى تَكفُرَ بِمُحَمَّدٍ وتَعبُدَ آلِهَتَنا! فَماذا كانَ بِلالٌ يَقولُ تَحتَ هذا العَذابِ الرَّهيب؟ كَلِمةً واحِدةً يُرَدِّدُها: «<b>أحَدٌ… أحَد</b>!» — أيْ رَبّي اللهُ الواحِدُ الأحَد، ولَن أُشرِكَ بِهِ أبَداً! كانَ كُلَّما زادوهُ عَذاباً زادَ ثَباتاً. ثُمَّ جاءَ أبو بَكرٍ الصِّدّيقُ فَاشتَراهُ بِمالِهِ وأعتَقَهُ، فَصارَ بِلالٌ حُرّاً، وصارَ بَعدَ ذلكَ <b>أوَّلَ مُؤَذِّنٍ في الإسلام</b> يَرفَعُ صَوتَهُ بِالأذانِ فَوقَ الكَعبة!',
    en:'Today\'s hero is the first voice of Islam: <b>Bilal ibn Rabah</b> (may Allah be pleased with him)! ☀️ He was a slave in Makkah, weak and poor, owning nothing of this world, owned by a harsh master from the disbelievers of Quraysh. When he heard of Islam, his heart believed at once, because he knew Allah created people equal, with no difference between master and slave except in piety. When his master found out, he raged and tried to force him from Islam through torture. He would take him out in the scorching midday heat onto the burning desert sand, throw him on his back, place a <b>huge boulder</b> on his chest, and say: I won\'t leave you until you disbelieve in Muhammad and worship our gods! What did Bilal say under this terrible torture? One word he kept repeating: "<b>Ahad… Ahad</b>!" — meaning my Lord is Allah, the One, the Only, and I will never associate anything with Him! The more they tortured him, the firmer he grew. Then Abu Bakr as-Siddiq came and bought him with his money and freed him, so Bilal became free, and later became <b>the first muezzin in Islam</b>, raising his voice with the adhan atop the Ka\'bah!' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «لِماذا لم يَقُل بِلالٌ كَلِمةَ الكُفرِ بِلِسانِهِ فَقَط لِيَنجوَ مِنَ العَذاب؟» 🤔', en:'A question crosses your mind: "Why didn\'t Bilal just say the words of disbelief with his tongue to escape the torture?" 🤔' },
  logic:{
    ar:'لِأنَّ بِلالاً فَهِمَ أنَّ <b>كَرامةَ الإيمانِ أغلى مِن راحةِ الجَسَد</b>. الألَمُ يَنتَهي، لكنَّ خِيانةَ اللهِ عارٌ لا يُغسَل. كانَ يُمكِنُهُ أن يَقولَ كَلِمةً ويَرتاح، لكنه آثَرَ صِدقَ القَلبِ واللِّسانِ مَعاً. وانظُر إلى المُعادَلةِ العَجيبة: سَيِّدُهُ كانَ يَملِكُ جِسمَهُ — يُعَذِّبُهُ ويُهينُه — لكنه لم يَستَطِع أبَداً أن يَملِكَ <b>قَلبَه</b>! فَالجَسَدُ قد يُقَيَّدُ، أمّا القَلبُ المُؤمِنُ فَحُرٌّ لا يُؤسَر. بِلالٌ كانَ «عَبداً» في عَينِ النّاس، لكنه كانَ أحَدَ أحرارِ التّاريخِ في الحَقيقة، بَينَما سَيِّدُهُ القَوِيُّ كانَ عَبداً ذَليلاً لِأصنامِهِ وغَضَبِه! ودَرسُ بِلالٍ لِكُلِّ طِفلٍ يَشعُرُ أنه ضَعيفٌ أو صَغيرٌ أو لا أحَدَ يَهتَمُّ بِه: قيمَتُكَ عِندَ اللهِ لَيسَت بِمالِكَ ولا قُوَّتِكَ ولا مَنصِبِ أهلِك، بَل بِإيمانِكَ وتَقواك. اللهُ رَفَعَ عَبداً فَقيراً حتّى صارَ صَوتُهُ يَملأُ السَّماءَ خَمسَ مَرّاتٍ كُلَّ يَوم، وذُكِرَ اسمُهُ في الجَنّة. فَكُن صادِقاً مَعَ اللهِ، يَرفَعكَ اللهُ كَما رَفَعَ بِلالاً.',
    en:'Because Bilal understood that <b>the dignity of faith is more precious than bodily comfort</b>. Pain ends, but betraying Allah is a disgrace that can\'t be washed away. He could have said a word and gotten relief, but he chose truthfulness of heart and tongue together. Look at the amazing equation: his master owned his body — torturing and humiliating him — but could never own his <b>heart</b>! The body may be chained, but a believing heart is free and cannot be captured. Bilal was a "slave" in people\'s eyes, but in truth he was one of history\'s free men, while his powerful master was a lowly slave to his idols and his rage! Bilal\'s lesson for every child who feels weak, small, or that no one cares about him: your worth with Allah isn\'t in your money, strength, or your family\'s status, but in your faith and piety. Allah raised a poor slave until his voice filled the sky five times a day, and his name was mentioned in Paradise. So be truthful with Allah, and Allah will raise you as He raised Bilal.' },
  myth:{ claim:{ ar:'«الضَّعيفُ الفَقيرُ لا قيمةَ لَهُ ولا يَكونُ بَطَلاً!»', en:'"The weak and poor have no worth and can\'t be heroes!"' },
         bust:{ ar:'بِلالٌ كانَ عَبداً فَقيراً، لكنَّ صِدقَ إيمانِهِ رَفَعَهُ حتّى صارَ أوَّلَ مُؤَذِّنٍ في الإسلام. قيمَتُكَ بِإيمانِكَ لا بِمالِكَ وقُوَّتِك.', en:'Bilal was a poor slave, but the sincerity of his faith raised him until he became the first muezzin in Islam. Your worth is in your faith, not your money or strength.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'«أحَدٌ أحَد»',en:'"Ahad, Ahad"'}, job:{ar:'كَلِمةُ بِلالٍ تَحتَ التَّعذيب',en:'Bilal\'s word under torture'} },
      { tool:{ar:'الصَّخرةُ على صَدرِه',en:'The boulder on his chest'}, job:{ar:'عَذابٌ لم يَكسِر إيمانَه',en:'A torture that didn\'t break his faith'} },
      { tool:{ar:'أبو بَكرٍ الصِّدّيق',en:'Abu Bakr as-Siddiq'}, job:{ar:'اشتَراهُ وأعتَقَه',en:'Bought and freed him'} },
      { tool:{ar:'بِلالٌ بَعدَ العِتق',en:'Bilal after freedom'}, job:{ar:'أوَّلُ مُؤَذِّنٍ في الإسلام',en:'The first muezzin in Islam'} },
    ] },
  reflection:{
    ayah:'﴿إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ ۚ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ﴾',
    ref:{ ar:'سورة الحُجُرات · ١٣', en:'Surah Al-Hujurat · 13' },
    explain:{
      ar:'هذِهِ الآيةُ هي قِصّةُ بِلالٍ كُلُّها في سَطر: المِيزانُ عِندَ اللهِ لَيسَ المالَ ولا اللَّونَ ولا النَّسَب، بَل <b>التَّقوى</b>. بِلالٌ الحَبَشِيُّ العَبدُ كانَ أكرَمَ عِندَ اللهِ مِن ساداتٍ كَثيرينَ كانوا أغنى وأقوى مِنه، لِأنَّ قَلبَهُ كانَ أتقى. فَلا تَنظُر إلى نَفسِكَ بِعَينِ النّاسِ التي تَزِنُ بِالمالِ والمَظهَر، بَل بِعَينِ اللهِ التي تَزِنُ بِالإيمانِ والعَمَل. وكُلَّما زادَت تَقواكَ، ارتَفَعَت مَنزِلَتُكَ عِندَ مَلِكِ المُلوك.',
      en:'This verse is Bilal\'s whole story in one line: the measure with Allah isn\'t money, color, or lineage, but <b>piety</b>. Bilal the Abyssinian slave was nobler with Allah than many masters who were richer and stronger than him, because his heart was more pious. So don\'t look at yourself through people\'s eyes that weigh by money and appearance, but through Allah\'s eyes that weigh by faith and deeds. The more your piety grows, the higher your rank rises with the King of kings.' } },
  card:{ name:{ar:'بِلالُ بنُ رَباح',en:'Bilal ibn Rabah'}, meaning:{ar:'عَبدٌ فَقيرٌ عُذِّبَ على الرَّملِ المُحرِقِ فَثَبَتَ يَقول «أحَدٌ أحَد»، فَرَفَعَهُ اللهُ أوَّلَ مُؤَذِّنٍ في الإسلام — قيمةُ المَرءِ بِتَقواه',en:'A poor slave tortured on burning sand who held firm saying "Ahad, Ahad," so Allah raised him as the first muezzin in Islam — a person\'s worth is in his piety'} },
  proof:{ ar:'قَلبي المُؤمِنُ حُرٌّ لا يُؤسَر، وقيمَتي عِندَ اللهِ بِإيماني لا بِمالي', en:'My believing heart is free and cannot be captured; my worth with Allah is by my faith, not my wealth' },
  dua:{ ar:'اللهُمَّ اجعَلني مِنَ المُتَّقينَ، وارفَع قَدري بِتَقواكَ وطاعَتِك', en:'O Allah, make me among the pious, and raise my rank through fearing and obeying You' },
  mission:{ ar:'⛓️ مُهِمّةُ البُطولة: بِلالٌ ثَبَتَ بِكَلِمةِ التَّوحيد. ردِّد اليومَ «لا إلهَ إلّا اللهُ وَحدَهُ لا شَريكَ لَه» عَشرَ مَرّاتٍ بِقَلبٍ حاضِر، وتَذَكَّر أنَّ هذِهِ الكَلِمةَ أغلى مِنَ الدُّنيا كُلِّها.', en:'⛓️ Hero Mission: Bilal held firm with the word of monotheism. Repeat today "There is no god but Allah alone, with no partner" ten times with a present heart, remembering this word is more precious than the whole world.' },
  badge:{ icon:'☀️', color:'#C26A1E', title:{ ar:'صاحِبُ «أحَد»', en:'The One of "Ahad"' } }
},

/* ───────────── 7 · The Family of Yasir & Sumayya ───────────── */
{
  id:'yasir', num:7, icon:'🤲', emoji:'🌹', color:'#A03050',
  title:{ ar:'آلُ ياسِر — أوَّلُ بَيتٍ صَبَرَ', en:'The Family of Yasir — The First Patient Household' },
  narration:{
    ar:'بَطَلُنا اليومَ <b>عائِلةٌ كامِلة</b> صَبَرَت مَعاً: ياسِرٌ، وزَوجَتُهُ سُمَيّة، وابنُهُما عَمّار رضي الله عنهم! 🌹 كانوا مِنَ الضُّعَفاءِ في مَكّة، ومِن أوائِلِ مَن آمَنَ بِالنَّبِيِّ ﷺ. ولِأنَّهُم لم يَكُن لَهُم عَشيرةٌ قَوِيّةٌ تَحميهِم، أنزَلَ بِهِمُ المُشرِكونَ أبشَعَ أنواعِ العَذاب: يُخرِجونَهُم إلى رَملِ مَكّةَ المُحرِقِ في شِدّةِ الحَرّ، ويُعَذِّبونَهُم لِيَترُكوا دينَهُم. وكانَ النَّبِيُّ ﷺ يَمُرُّ علَيهِم وهُم يُعَذَّبون، فَلا يَملِكُ لَهُم في تِلكَ المَرحَلةِ إلّا أن يُثَبِّتَهُم بِأعظَمِ بِشارة، فَيَقول: «<b>صَبراً آلَ ياسِر، فإنَّ مَوعِدَكُمُ الجَنّة</b>». فَكانَت هذِهِ الكَلِمةُ تُحَوِّلُ ألَمَهُم إلى أمَلٍ ونور. أمّا سُمَيّةُ — هذِهِ المَرأةُ العَجوزُ الضَّعيفةُ — فَرَفَضَت أن تَكفُرَ مَهما عَذَّبوها، حتّى قَتَلَها أبو جَهلٍ ظُلماً، فَكانَت <b>أوَّلَ شَهيدةٍ في الإسلام</b>! ماتَت وهي ثابِتةٌ على إيمانِها، فَنالَت شَرَفاً لا يُنالُ: أوَّلُ نَفسٍ تُقَدَّمُ فِداءً لِهذا الدّينِ كانَت نَفسَ امرَأةٍ مُؤمِنةٍ شُجاعة.',
    en:'Today\'s hero is <b>a whole family</b> who endured together: Yasir, his wife Sumayya, and their son Ammar (may Allah be pleased with them)! 🌹 They were among the weak in Makkah, and among the first to believe in the Prophet ﷺ. Because they had no strong tribe to protect them, the polytheists inflicted the ugliest torture on them: taking them out onto Makkah\'s burning sand in intense heat, torturing them to make them leave their faith. The Prophet ﷺ would pass by them as they were tortured, and at that stage could do nothing for them but strengthen them with the greatest glad tidings, saying: "<b>Be patient, family of Yasir, for your appointed place is Paradise</b>." These words turned their pain into hope and light. As for Sumayya — this weak, elderly woman — she refused to disbelieve no matter how they tortured her, until Abu Jahl killed her unjustly, and she became <b>the first martyr in Islam</b>! She died firm upon her faith, attaining an unmatched honor: the first soul offered as a sacrifice for this religion was the soul of a brave, believing woman.' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «أينَ كانَ النَّبِيُّ ﷺ؟ ولِماذا لم يُنقِذهُم مِنَ العَذاب؟» 🤔', en:'A question crosses your mind: "Where was the Prophet ﷺ? Why didn\'t he save them from the torture?" 🤔' },
  logic:{
    ar:'سُؤالٌ مُهِمّ! في تِلكَ الفَترةِ المُبَكِّرةِ كانَ المُسلِمونَ قِلّةً مُستَضعَفينَ في مَكّة، لا يَملِكونَ قُوّةً ولا جَيشاً، والأمرُ لم يَأذَن بِهِ اللهُ بَعدُ بِالقِتال. فَكانَتِ الحِكمةُ في الصَّبرِ والثَّباتِ حتّى يَأذَنَ الله. لكنِ انتَبِه لِلسِّرِّ العَظيم: العَذابُ لم يَنتَصِر! المُشرِكونَ أرادوا أن يُطفِئوا نورَ الإيمانِ في صُدورِ آلِ ياسِر، فَماذا كانَتِ النَّتيجة؟ ازدادَ النّورُ سُطوعاً، وصارَ اسمُ سُمَيّةَ خالِداً يَذكُرُهُ المُسلِمونَ بِالفَخرِ إلى اليوم، بَينَما صارَ اسمُ أبي جَهلٍ رَمزاً لِلظُّلمِ والخِزي! الظّالِمُ يَملِكُ أن يُؤذِيَ الجَسَد، لكنه لا يَملِكُ أبَداً أن يَهزِمَ الإيمان. ودَرسُ آلِ ياسِرٍ لَنا: <b>الثَّباتُ أسهَلُ مَعَ الأهلِ والإخوة</b>. حينَ تَكونُ العائِلةُ كُلُّها على الخَير، يُقَوّي بَعضُها بَعضاً. اجعَل بَيتَكَ بَيتَ إيمانٍ: تُذَكِّرُ أخاكَ، ويُذَكِّرُكَ أبوك، وتَدعو لِأُمِّك. ومَوعِدُكُم جَميعاً — كَآلِ ياسِر — الجَنّة. وتَذَكَّر: مَهما طالَ البَلاءُ فالعاقِبةُ لِلمُؤمِن، والجَنّةُ تُنسي كُلَّ ألَم.',
    en:'An important question! In that early period the Muslims were a weak minority in Makkah, with no power or army, and Allah had not yet permitted fighting. So the wisdom lay in patience and steadfastness until Allah gave permission. But note the great secret: the torture did not win! The polytheists wanted to extinguish the light of faith in the chests of Yasir\'s family, and what was the result? The light grew brighter, and Sumayya\'s name became eternal, mentioned by Muslims with pride to this day, while Abu Jahl\'s name became a symbol of oppression and disgrace! An oppressor can harm the body, but he can never defeat faith. And the lesson of Yasir\'s family for us: <b>steadfastness is easier with family and siblings</b>. When the whole family is upon good, they strengthen one another. Make your home a home of faith: you remind your brother, your father reminds you, and you pray for your mother. And your appointed place all together — like Yasir\'s family — is Paradise. Remember: however long the hardship, the outcome belongs to the believer, and Paradise makes you forget every pain.' },
  myth:{ claim:{ ar:'«إذا أصابَ المُؤمِنَ بَلاءٌ شَديدٌ فَهذا دَليلُ أنَّ اللهَ تَخَلّى عَنه!»', en:'"If a believer suffers severe hardship, it proves Allah has abandoned him!"' },
         bust:{ ar:'آلُ ياسِرٍ عُذِّبوا أشَدَّ العَذاب، فَبَشَّرَهُمُ النَّبِيُّ ﷺ بِالجَنّة. البَلاءُ امتِحانُ مَحَبّةٍ ورِفعةٌ، والعاقِبةُ دائِماً لِلمُؤمِنِ الصّابِر.', en:'The family of Yasir were tortured most severely, and the Prophet ﷺ gave them glad tidings of Paradise. Hardship is a test of love and a raising of rank; the outcome always belongs to the patient believer.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'سُمَيّة',en:'Sumayya'}, job:{ar:'أوَّلُ شَهيدةٍ في الإسلام',en:'The first martyr in Islam'} },
      { tool:{ar:'«مَوعِدُكُمُ الجَنّة»',en:'"Your appointed place is Paradise"'}, job:{ar:'تَثبيتُ النَّبِيِّ ﷺ لَهُم',en:'The Prophet\'s ﷺ words strengthening them'} },
      { tool:{ar:'أبو جَهل',en:'Abu Jahl'}, job:{ar:'الظّالِمُ الذي صارَ رَمزَ الخِزي',en:'The oppressor who became a symbol of disgrace'} },
      { tool:{ar:'بَيتُ آلِ ياسِر',en:'The household of Yasir'}, job:{ar:'عائِلةٌ ثَبَتَت على الإيمانِ مَعاً',en:'A family steadfast in faith together'} },
    ] },
  reflection:{
    ayah:'﴿أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ﴾',
    ref:{ ar:'سورة العَنكَبوت · ٢', en:'Surah Al-Ankabut · 2' },
    explain:{
      ar:'يُخبِرُنا اللهُ بِقانونٍ مُهِمّ: الإيمانُ لَيسَ كَلِمةً تُقالُ بِاللِّسانِ فَقَط، بَل لا بُدَّ مِنِ امتِحانٍ يُثبِتُ صِدقَه. كَالذَّهَبِ الذي يُوضَعُ في النّارِ لِيَظهَرَ نَقاؤُه. آلُ ياسِرٍ امتُحِنوا فَنَجَحوا بِامتِياز، فَكانوا قُدوةً لِكُلِّ مُؤمِنٍ بَعدَهُم. فَإذا واجَهتَ صُعوبةً بِسَبَبِ دينِك — كَأن يَسخَرَ مِنكَ أحَدٌ لِأنَّكَ تُصَلّي — فَاعلَم أنَّهُ امتِحانٌ صَغيرٌ يَرفَعُ دَرَجَتَك. اثبُت، فالنَّجاحُ في الامتِحانِ يوصِلُ إلى أعلى الدَّرَجات.',
      en:'Allah tells us an important law: faith isn\'t just a word said with the tongue; there must be a test proving its sincerity. Like gold placed in fire to show its purity. The family of Yasir were tested and passed with distinction, becoming role models for every believer after them. So if you face difficulty because of your faith — like someone mocking you because you pray — know it\'s a small test that raises your rank. Hold firm, for passing the test leads to the highest ranks.' } },
  card:{ name:{ar:'آلُ ياسِر',en:'The Family of Yasir'}, meaning:{ar:'عائِلةٌ ثَبَتَت على الإيمانِ تَحتَ التَّعذيب، وسُمَيّةُ أوَّلُ شَهيدةٍ في الإسلام — بَشَّرَهُمُ النَّبِيُّ ﷺ بِالجَنّة، والثَّباتُ أقوى مَعَ الأهل',en:'A family steadfast in faith under torture, with Sumayya the first martyr in Islam — the Prophet ﷺ gave them tidings of Paradise; steadfastness is stronger with family'} },
  proof:{ ar:'البَلاءُ امتِحانٌ يَرفَعُ دَرَجَتي، والثَّباتُ أقوى حينَ يَكونُ بَيتي بَيتَ إيمان', en:'Hardship is a test that raises my rank, and steadfastness is stronger when my home is a home of faith' },
  dua:{ ar:'اللهُمَّ اجعَل بَيتَنا بَيتَ إيمانٍ وطاعة، واجمَعنا في جَنَّتِكَ كَما جَمَعتَ آلَ ياسِر', en:'O Allah, make our home a home of faith and obedience, and gather us in Your Paradise as You gathered the family of Yasir' },
  mission:{ ar:'🤲 مُهِمّةُ البُطولة: كُن سَبَبَ خَيرٍ لِأهلِك: ذَكِّر أخاكَ أو صَديقَكَ بِالصَّلاةِ اليومَ بِلُطف، أوِ ادعُ لِوالِدَيكَ بِظَهرِ الغَيب — فَالثَّباتُ يَقوى حينَ نُعينُ بَعضَنا على الخَير.', en:'🤲 Hero Mission: Be a cause of good for your family: gently remind your brother or friend about prayer today, or pray for your parents in their absence — steadfastness grows when we help one another toward good.' },
  badge:{ icon:'🌹', color:'#A03050', title:{ ar:'بَطَلُ الصَّبر', en:'Hero of Patience' } }
},

/* ───────────── 8 · Mashitat Fir'awn — the Hair-comber & Her Children ───────────── */
{
  id:'mashita', num:8, icon:'💇', emoji:'👶', color:'#A8527C',
  title:{ ar:'ماشِطةُ فِرعَون — أُمٌّ وأطفالُها', en:'The Hair-comber of Pharaoh — a Mother & Her Children' },
  narration:{
    ar:'بَطَلَتُنا اليومَ امرَأةٌ مُؤمِنةٌ شَهِدَ النَّبِيُّ ﷺ على عِطرِها في الجَنّة! 👶 كانَت تَعمَلُ في قَصرِ فِرعَونَ <b>ماشِطةً</b> (تُمَشِّطُ شَعرَ ابنةِ فِرعَون)، وكانَت تُؤمِنُ بِاللهِ الواحِدِ في السِّرّ. وبَينَما هي تُمَشِّطُ شَعرَ البِنتِ يَوماً، سَقَطَ المُشطُ مِن يَدِها، فَقالَت: «<b>بِسمِ الله</b>». فَقالَتِ البِنتُ مُستَغرِبة: أبي؟! (تَظُنُّ أنها تَقصِدُ فِرعَون). فَقالَتِ الماشِطةُ بِشَجاعة: «لا، بَل <b>رَبّي ورَبُّكِ ورَبُّ أبيكِ اللهُ</b>». فَأخبَرَتِ البِنتُ أباها، فَاستَدعى فِرعَونُ الماشِطةَ وأمَرَها أن تَكفُرَ بِاللهِ وتَعبُدَه هو، فَرَفَضَت وثَبَتَت على إيمانِها. فَأمَرَ الطّاغِيةُ بِأن تُحمى نُقرةٌ عَظيمةٌ مِنَ النُّحاسِ على النّارِ حتّى تَغلِيَ، وأرادَ أن يُلقِيَها وأطفالَها فيها واحِداً واحِداً أمامَ عَينَيها لِيُرجِعَها! وبَدَأ يُلقي أبناءَها، وهي ثابِتةٌ صابِرة. حتّى جاءَ دَورُ <b>طِفلِها الرَّضيع</b>، فَتَرَدَّدَت قَليلاً مِن شِدّةِ شَفَقَتِها علَيه… فَأنطَقَ اللهُ الرَّضيعَ بِمُعجِزةٍ وقال: «<b>يا أُمّاه اصبِري فإنَّكِ على الحَقّ</b>»! فَثَبَتَت وألقَوها مَعَ أطفالِها، فَصاروا جَميعاً إلى الجَنّة. وفي لَيلةِ الإسراءِ شَمَّ النَّبِيُّ ﷺ رائِحةً طَيِّبةً، فَسَألَ جِبريلَ عَنها، فَقال: هذِهِ رائِحةُ ماشِطةِ بِنتِ فِرعَونَ وأولادِها (رواه أحمد).',
    en:'Today’s hero is a believing woman whose fragrance the Prophet ﷺ witnessed in Paradise! 👶 She worked in Pharaoh’s palace as a <b>hair-comber</b> (combing the hair of Pharaoh’s daughter), and she secretly believed in the One God. One day, while combing the girl’s hair, the comb fell from her hand, so she said: “<b>Bismillah</b> (in the name of Allah).” The girl asked, surprised: “My father?!” (thinking she meant Pharaoh). The comber said bravely: “No — <b>my Lord, your Lord, and your father’s Lord is Allah</b>.” The girl told her father, so Pharaoh summoned the comber and ordered her to disbelieve in Allah and worship him, but she refused and held firm. The tyrant ordered a huge vat of copper heated on the fire until it boiled, and wanted to throw her and her children into it one by one before her eyes to turn her back! He began throwing her children in, while she stood firm and patient. Until it came to her <b>nursing baby</b>, and she hesitated a little out of deep tenderness for him… so Allah made the baby speak by a miracle, saying: “<b>O mother, be patient, for you are upon the truth</b>!” So she held firm, and they threw her in with her children, and they all went to Paradise together. On the night of the Isra’, the Prophet ﷺ smelled a beautiful fragrance and asked Jibril about it; he said: this is the fragrance of the hair-comber of Pharaoh’s daughter and her children (Ahmad).' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ تَصبِرُ أُمٌّ وتَرى أطفالَها أمامَها، ولا تَقولُ كَلِمةً واحِدةً لِتُنقِذَهُم؟» 🤔', en:'A question crosses your mind: “How can a mother be patient seeing her children before her, and not say one word to save them?” 🤔' },
  logic:{
    ar:'سُؤالٌ صَعبٌ وجَوابُهُ عَظيم: لِأنَّ الماشِطةَ كانَت تُحِبُّ أطفالَها حُبّاً عَظيماً، ولِأنها تُحِبُّهُم أرادَت لَهُمُ الخَيرَ الحَقيقيَّ والباقي: <b>الجَنّةَ مَعَها</b>، لا أن يَعيشوا أيّاماً قَليلةً ثُمَّ يَموتوا على الكُفر. هي لم تَختَر أن يَموتَ أطفالُها، بَل الطّاغِيةُ هو الذي قَتَلَهُم ظُلماً — لكنها رَفَضَت أن تُنقِذَ أجسادَهُمُ الفانِيةَ بِأن تَخسَرَ أرواحَهُمُ الباقِية. ولاحِظ مُعجِزةَ اللهِ العَجيبة: لَمّا ضَعُفَ قَلبُ الأُمِّ لَحظةً واحِدةً عِندَ رَضيعِها، أرسَلَ اللهُ لَها التَّثبيتَ مِن أصغَرِ مَخلوقٍ — طِفلٍ رَضيعٍ يَنطِقُ! «يا أُمّاه اصبِري فإنَّكِ على الحَقّ». فاللهُ لا يَترُكُ عَبدَهُ الصّادِقَ وَحدَهُ في لَحظةِ الشِّدّة، بَل يُرسِلُ لَهُ ما يُثَبِّتُهُ مِن حَيثُ لا يَحتَسِب. ودَرسُها العَظيمُ لَكَ: الإيمانُ بِاللهِ أغلى مِن أعَزِّ ما نَملِك، حتّى الأبناء. وهذا لا يَعني أنَّنا لا نُحِبُّ أهلَنا — بَل نُحِبُّهُم في اللهِ، ونُريدُ لَهُمُ الجَنّةَ، ونَجتَمِعُ بِهِم فيها لا نَفتَرِقُ أبَداً. وانظُرِ النَّتيجة: ظَنَّ فِرعَونُ أنه انتَصَرَ، لكنَّ الماشِطةَ وأطفالَها صاروا عِطراً في الجَنّةِ شَمَّهُ سَيِّدُ الخَلقِ ﷺ، واسمُها خالِدٌ نَذكُرُهُ بِالحُبّ، وفِرعَونُ غَرِقَ ولُعِنَ. هكذا يَنتَصِرُ الإيمانُ دائِماً.',
    en:'A hard question with a great answer: because the comber loved her children deeply, and because she loved them she wanted for them the true, lasting good — <b>Paradise with her</b> — not that they live a few days and then die upon disbelief. She didn’t choose for her children to die; the tyrant is the one who unjustly killed them — but she refused to save their perishing bodies by losing their everlasting souls. And notice Allah’s amazing miracle: when the mother’s heart weakened for a single moment at her baby, Allah sent her steadfastness from the smallest creature — a nursing infant who spoke! “O mother, be patient, for you are upon the truth.” Allah never leaves His sincere servant alone in the moment of hardship; He sends what strengthens them from where they don’t expect. Her great lesson for you: faith in Allah is more precious than the dearest things we own, even children. This doesn’t mean we don’t love our families — rather we love them for Allah’s sake, want Paradise for them, and reunite with them there, never to part. And look at the result: Pharaoh thought he won, but the comber and her children became a fragrance in Paradise smelled by the master of creation ﷺ, her name eternal and remembered with love, while Pharaoh drowned and was cursed. This is how faith always wins.' },
  myth:{ claim:{ ar:'«الثَّباتُ يَعني أن نَكرَهَ أهلَنا ونُضَحِّيَ بِهِم!»', en:'“Steadfastness means hating our family and sacrificing them!”' },
         bust:{ ar:'بَلِ الماشِطةُ ثَبَتَت لِأنها أحَبَّت أطفالَها حَقّاً، فَأرادَت لَهُمُ الجَنّةَ الباقِيةَ مَعَها لا حَياةً فانِيةً على الكُفر. نُحِبُّ أهلَنا في اللهِ ونُريدُ لَهُمُ الخَيرَ الأبَدِيّ.', en:'Rather, the comber held firm because she truly loved her children, wanting for them lasting Paradise with her, not a perishing life upon disbelief. We love our families for Allah’s sake and want eternal good for them.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'سُقوطُ المُشط',en:'The fallen comb'}, job:{ar:'قالَت عِندَهُ «بِسمِ الله»',en:'At it she said “Bismillah”'} },
      { tool:{ar:'«رَبّي ورَبُّكِ اللهُ»',en:'“My Lord and yours is Allah”'}, job:{ar:'كَلِمةُ الحَقِّ التي ثَبَتَت علَيها',en:'The word of truth she held to'} },
      { tool:{ar:'الطِّفلُ الرَّضيع',en:'The nursing baby'}, job:{ar:'أنطَقَهُ اللهُ: «اصبِري فإنَّكِ على الحَقّ»',en:'Allah made him speak: “Be patient, you are upon the truth”'} },
      { tool:{ar:'رائِحَتُها الطَّيِّبة',en:'Her sweet fragrance'}, job:{ar:'شَمَّها النَّبِيُّ ﷺ لَيلةَ الإسراء',en:'The Prophet ﷺ smelled it on the Night Journey'} },
    ] },
  reflection:{
    ayah:'﴿إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ﴾',
    ref:{ ar:'سورة الزُّمَر · ١٠', en:'Surah Az-Zumar · 10' },
    explain:{
      ar:'كُلُّ الأعمالِ لَها أجرٌ مَعدودٌ مَعلوم، إلّا <b>الصَّبر</b> فَأجرُهُ «بِغَيرِ حِساب» — أيْ بِلا حَدٍّ ولا عَدّ! والماشِطةُ صَبَرَت أعظَمَ صَبرٍ يُتَصَوَّر، فَكانَ جَزاؤُها أعظَمَ جَزاء: الجَنّةُ هي وأطفالُها، وعِطرٌ خالِدٌ يَفوحُ في السَّماء. تَأمَّل: لَحَظاتُ ألَمٍ قَصيرةٌ في الدُّنيا، مُقابِلَ نَعيمٍ لا يَنتَهي في الآخِرة. فإذا مَرَرتَ بِشِدّةٍ بِسَبَبِ دينِك، تَذَكَّر أنَّ اللهَ يَملأُ ميزانَكَ بِالأجرِ بِلا حِساب، وأنه يُرسِلُ لَكَ التَّثبيتَ كَما أرسَلَهُ لِلماشِطةِ على لِسانِ رَضيعِها.',
      en:'Every deed has a counted, known reward — except <b>patience</b>, whose reward is “without measure” — with no limit or count! The comber endured the greatest patience imaginable, so her reward was the greatest: Paradise for her and her children, and an eternal fragrance wafting in the heavens. Reflect: brief moments of pain in this world, against unending bliss in the Hereafter. So if you face hardship because of your faith, remember that Allah fills your scale with reward without measure, and that He sends you steadfastness as He sent it to the comber through the tongue of her baby.' } },
  card:{ name:{ar:'ماشِطةُ بِنتِ فِرعَون',en:'The Hair-comber of Pharaoh’s Daughter'}, meaning:{ar:'أُمٌّ مُؤمِنةٌ ثَبَتَت هي وأطفالُها على الإيمانِ حتّى الشَّهادة، وأنطَقَ اللهُ رَضيعَها يُثَبِّتُها — فَصاروا عِطراً في الجَنّةِ شَمَّهُ النَّبِيُّ ﷺ',en:'A believing mother who held firm with her children to martyrdom, whose baby Allah made speak to strengthen her — they became a fragrance in Paradise the Prophet ﷺ smelled'} },
  proof:{ ar:'الإيمانُ أغلى مِن أعَزِّ ما أملِك، واللهُ يُثَبِّتُني مِن حَيثُ لا أحتَسِب', en:'Faith is more precious than the dearest I own, and Allah strengthens me from where I don’t expect' },
  dua:{ ar:'اللهُمَّ يا مُثَبِّتَ القُلوب، ثَبِّتني وأهلي على دينِك، واجمَعنا في جَنَّتِكَ لا نَفتَرِق', en:'O Allah, O Steadier of hearts, keep me and my family firm on Your religion, and gather us in Your Paradise, never to part' },
  mission:{ ar:'💇 مُهِمّةُ البُطولة: الماشِطةُ بَدَأت ثَباتَها بِكَلِمةِ «بِسمِ الله». اجعَلها مِفتاحَ يَومِك: قُل «بِسمِ الله» قَبلَ كُلِّ عَمَل (الأكل، الخُروج، الدِّراسة)، وادعُ اللهَ أن يَجمَعَكَ بِأهلِكَ في الجَنّة.', en:'💇 Hero Mission: The comber began her steadfastness with “Bismillah.” Make it the key to your day: say “Bismillah” before every act (eating, leaving home, studying), and pray that Allah gathers you with your family in Paradise.' },
  badge:{ icon:'👶', color:'#A8527C', title:{ ar:'بَطَلةُ التَّثبيت', en:'Hero of Steadfast Faith' } }
},

/* ───────────── 9 · Khubayb — Prayer Before Farewell ───────────── */
{
  id:'khubayb', num:9, icon:'🕌', emoji:'📿', color:'#33691E',
  title:{ ar:'خُبَيبٌ — رَكعَتانِ قَبلَ الوَداع', en:'Khubayb — Two Rak\'ahs Before Farewell' },
  narration:{
    ar:'بَطَلُنا اليومَ صَحابِيٌّ عَلَّمَ الأُمّةَ كُلَّها كَيفَ يَكونُ الثَّباتُ حتّى آخِرِ لَحظة: <b>خُبَيبُ بنُ عَدِيٍّ</b> رضي الله عنه! 📿 أرسَلَهُ النَّبِيُّ ﷺ في مُهِمّة، فَخَدَعَهُ أعداؤُهُ وأسَروه وباعوهُ لِقَومٍ أرادوا قَتلَهُ انتِقاماً. حَبَسوهُ عِندَهُم أيّاماً، ثُمَّ أخرَجوهُ لِيَقتُلوه. وهُنا حَدَثَ المَوقِفُ الذي لا يُنسى: طَلَبَ خُبَيبٌ مِنهُم أن يَترُكوهُ يُصَلّي <b>رَكعَتَين</b> قَبلَ مَوتِه. فَتَرَكوه. فَصَلّى رَكعَتَينِ خاشِعَتَينِ جَميلَتَين، ثُمَّ قال كَلِمةً عَظيمة: «<b>لَولا أن تَظُنّوا أنَّ ما بي جَزَعٌ مِنَ المَوتِ لَزِدتُ</b>» — أيْ: لَولا خَوفي أن تَظُنّوا أنّي أُطيلُ الصَّلاةَ خَوفاً وهَلَعاً مِنَ المَوت، لَأطَلتُها أكثَر، فَأنا لا أخافُ المَوتَ أبَداً! فَكانَ خُبَيبٌ <b>أوَّلَ مَن سَنَّ الرَّكعَتَينِ عِندَ القَتلِ صَبراً</b>. ثُمَّ رَفَعَ يَدَيهِ ودَعا اللهَ بِثَباتٍ عَجيب. ماتَ خُبَيبٌ، لكنه ماتَ وقَلبُهُ مُعَلَّقٌ بِالصَّلاةِ ورَبِّه، فَصارَ قُدوةً في أنَّ المُؤمِنَ لا يَترُكُ صِلَتَهُ بِاللهِ مَهما اشتَدَّ الكَرب.',
    en:'Today\'s hero is a companion who taught the whole ummah how steadfastness looks until the last moment: <b>Khubayb ibn Adiy</b> (may Allah be pleased with him)! 📿 The Prophet ﷺ sent him on a mission, but his enemies deceived and captured him, then sold him to a people who wanted to kill him in revenge. They imprisoned him for days, then brought him out to kill him. Here came the unforgettable moment: Khubayb asked them to let him pray <b>two rak\'ahs</b> before his death. They allowed it. He prayed two humble, beautiful rak\'ahs, then said great words: "<b>Were it not that you might think my delay is from fear of death, I would have prayed more</b>" — meaning: if I weren\'t afraid you\'d think I\'m prolonging the prayer out of fear and panic of death, I would have made it longer, for I do not fear death at all! So Khubayb became <b>the first to establish the practice of two rak\'ahs before being killed, in patience</b>. Then he raised his hands and prayed to Allah with astonishing steadfastness. Khubayb died, but he died with his heart attached to prayer and his Lord, becoming a role model that the believer never abandons his connection with Allah however severe the distress.' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ يُفَكِّرُ إنسانٌ في الصَّلاةِ وهو على وَشكِ المَوت؟» 🤔', en:'A question crosses your mind: "How does someone think about prayer when about to die?" 🤔' },
  logic:{
    ar:'لِأنَّ الصَّلاةَ بِالنِّسبةِ لِخُبَيبٍ لم تَكُن واجِباً ثَقيلاً، بَل كانَت <b>أحَبَّ شَيءٍ إلى قَلبِه</b>، وراحَتَهُ ولِقاءَهُ بِرَبِّه. فَفي أصعَبِ لَحَظاتِ حَياتِهِ، أرادَ أن يَلقى اللهَ وهو ساجِدٌ بَينَ يَدَيه. تَخَيَّل: لو كانَتِ الصَّلاةُ ثَقيلةً علَيهِ، لَكانَت آخِرَ ما يُفَكِّرُ فيهِ في تِلكَ اللَّحظة! لكنه طَلَبَها بِنَفسِهِ، لِأنَّ مَن أحَبَّ شَيئاً جَعَلَهُ آخِرَ ما يُفارِقُه. ودَرسُ خُبَيبٍ العَمَلِيُّ لَكَ: كَيفَ هي عَلاقَتُكَ بِصَلاتِك؟ هل هي عِبءٌ تُؤَخِّرُهُ أمْ كَنزٌ تَنتَظِرُه؟ ابدَأ مِنَ الآنَ بِأن تُحِبَّ صَلاتَك، فَتُصَلِّيَها بِخُشوعٍ وفي وَقتِها، حتّى تَصيرَ راحةَ قَلبِكَ كَما كانَت راحةَ خُبَيب. ولاحِظ أيضاً شَجاعَتَهُ النّادِرة: لم يُرِد حتّى أن يَظُنَّ أعداؤُهُ أنه خائِفٌ مِنَ المَوت! المُؤمِنُ القَوِيُّ لا يُذِلُّهُ الخَوفُ، لِأنه يَعلَمُ أنَّ المَوتَ لَيسَ نِهايةً بَل بِدايةُ لِقاءٍ بِالحَبيب. مَن عاشَ مَعَ اللهِ، ماتَ وهو مُطمَئِنٌّ إلَيه.',
    en:'Because prayer, for Khubayb, wasn\'t a heavy duty but <b>the most beloved thing to his heart</b>, his rest and his meeting with his Lord. In the hardest moments of his life, he wanted to meet Allah while prostrating before Him. Imagine: if prayer were burdensome to him, it would be the last thing he\'d think of in that moment! But he asked for it himself, because whoever loves something makes it the last thing to part from. Khubayb\'s practical lesson for you: how is your relationship with your prayer? Is it a burden you delay or a treasure you await? Start now by loving your prayer, praying it with focus and on time, until it becomes the rest of your heart as it was Khubayb\'s rest. Notice also his rare courage: he didn\'t even want his enemies to think he feared death! The strong believer isn\'t humbled by fear, because he knows death isn\'t an end but the beginning of meeting the Beloved. Whoever lived with Allah dies at peace with Him.' },
  myth:{ claim:{ ar:'«الصَّلاةُ واجِبٌ ثَقيلٌ نُؤَخِّرُهُ كُلَّما استَطَعنا!»', en:'"Prayer is a heavy duty we delay whenever we can!"' },
         bust:{ ar:'خُبَيبٌ طَلَبَ الصَّلاةَ في آخِرِ لَحَظاتِ حَياتِه، لِأنها كانَت راحَتَهُ ولِقاءَهُ بِرَبِّه. مَن أحَبَّ صَلاتَهُ جَعَلَها كَنزَهُ لا عِبأَه.', en:'Khubayb asked for prayer in the last moments of his life, because it was his rest and his meeting with his Lord. Whoever loves his prayer makes it his treasure, not his burden.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَعناه', en:'Match each thing to its meaning' },
    pairs:[
      { tool:{ar:'خُبَيبُ بنُ عَدِيّ',en:'Khubayb ibn Adiy'}, job:{ar:'ثَبَتَ على دينِهِ حتّى المَوت',en:'Held firm to his faith until death'} },
      { tool:{ar:'الرَّكعَتان',en:'The two rak\'ahs'}, job:{ar:'سَنَّ صَلاتَهُما قَبلَ القَتل',en:'He established praying them before being killed'} },
      { tool:{ar:'«لَولا أن تَظُنّوا»',en:'"Were it not that you might think"'}, job:{ar:'لم يَخَف مِنَ المَوتِ أبَداً',en:'He never feared death at all'} },
      { tool:{ar:'الصَّلاةُ عِندَ خُبَيب',en:'Prayer for Khubayb'}, job:{ar:'راحةُ القَلبِ ولِقاءُ الرَّبّ',en:'The heart\'s rest and meeting the Lord'} },
    ] },
  reflection:{
    ayah:'﴿وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ﴾',
    ref:{ ar:'سورة البَقَرة · ٤٥', en:'Surah Al-Baqarah · 45' },
    explain:{
      ar:'أمَرَنا اللهُ أن نَستَعينَ بِالصَّبرِ والصَّلاةِ عِندَ كُلِّ شِدّة. ولاحِظ: الصَّلاةُ «كَبيرةٌ» — أيْ ثَقيلةٌ — «إلّا على الخاشِعين». فَالذينَ يُحِبّونَ اللهَ ويَخشَعونَ في صَلاتِهِم تَكونُ الصَّلاةُ عِندَهُم خَفيفةً مُحَبَّبةً، بَل راحةً يَلجَؤونَ إلَيها. خُبَيبٌ كانَ مِن هؤلاءِ الخاشِعين، فَلِذلكَ كانَتِ الصَّلاةُ مَلاذَهُ حتّى عِندَ المَوت. فَكُلَّما خَشَعَ قَلبُكَ في الصَّلاة، صارَت أحَبَّ إلَيكَ وأخَفَّ علَيك، وصِرتَ تَستَعينُ بِها على كُلِّ هَمّ.',
      en:'Allah commanded us to seek help through patience and prayer in every hardship. Notice: prayer is "great" — i.e., heavy — "except upon the humbly submissive." Those who love Allah and have focus in their prayer find prayer light and beloved, even a rest they retreat to. Khubayb was among these humble ones, so prayer was his refuge even at death. The more your heart submits in prayer, the more beloved and light it becomes, and you come to seek its help against every worry.' } },
  card:{ name:{ar:'خُبَيبُ بنُ عَدِيّ',en:'Khubayb ibn Adiy'}, meaning:{ar:'صَحابِيٌّ صَلّى رَكعَتَينِ قَبلَ قَتلِهِ ولم يَخَفِ المَوت، فَسَنَّ سُنّةَ الرَّكعَتَينِ عِندَ الشَّهادة — الصَّلاةُ راحةُ قَلبِ المُؤمِن',en:'A companion who prayed two rak\'ahs before his killing and feared not death, establishing the practice of two rak\'ahs at martyrdom — prayer is the believer\'s heart-rest'} },
  proof:{ ar:'صَلاتي راحةُ قَلبي ولِقائي بِرَبّي، لا عِبءٌ أُؤَخِّرُه', en:'My prayer is my heart\'s rest and my meeting with my Lord, not a burden I delay' },
  dua:{ ar:'اللهُمَّ اجعَلِ الصَّلاةَ قُرّةَ عَيني وراحةَ قَلبي، وثَبِّتني علَيها إلى أن ألقاك', en:'O Allah, make prayer the delight of my eye and the rest of my heart, and keep me firm upon it until I meet You' },
  mission:{ ar:'🕌 مُهِمّةُ البُطولة: صَلِّ صَلاةً واحِدةً اليومَ كَأنها آخِرُ صَلاةٍ في حَياتِك — بِخُشوعٍ وتَمَهُّلٍ وحُضورِ قَلب، كَما صَلّى خُبَيب. وستَكتَشِفُ حَلاوةً جَديدة.', en:'🕌 Hero Mission: Pray one prayer today as if it were the last prayer of your life — with focus, calm, and a present heart, as Khubayb prayed. You\'ll discover a new sweetness.' },
  badge:{ icon:'📿', color:'#33691E', title:{ ar:'مُحِبُّ الصَّلاة', en:'Lover of Prayer' } }
},

/* ───────────── 10 · Habib the Carpenter — the Believer of Ya-Sin ───────────── */
{
  id:'habib', num:10, icon:'🏃', emoji:'💚', color:'#1E8C7E',
  title:{ ar:'مُؤمِنُ سورةِ يس — يا لَيتَ قَومي يَعلَمون', en:'The Believer of Ya-Sin — "If Only My People Knew"' },
  narration:{
    ar:'بَطَلُنا اليومَ رَجُلٌ عادِيٌّ بَسيطٌ خَلَّدَ اللهُ قِصَّتَهُ في سورةِ يس: <b>مُؤمِنُ آلِ ياسين</b> (يُعرَفُ بِحَبيبٍ النَّجّار)! 💚 كانَ في قَريةٍ جاءَها رُسُلٌ يَدعونَ النّاسَ لِعِبادةِ اللهِ الواحِد، فَكَذَّبَهُمُ القَومُ وآذَوهُم. وكانَ هذا الرَّجُلُ يَسكُنُ في أقصى المَدينة، فَلَمّا سَمِعَ بِالرُّسُلِ آمَنَ بِهِم فَوراً. وبَدَلَ أن يَجلِسَ في بَيتِهِ خائِفاً، فَعَلَ شَيئاً شُجاعاً: ﴿<b>وجاءَ مِن أقصى المَدينةِ رَجُلٌ يَسعى</b>﴾ — جاءَ يَركُضُ مُسرِعاً لِيَنصُرَ الرُّسُلَ ويَدعوَ قَومَهُ لِلإيمان! قالَ لَهُم: ﴿يا قَومِ اتَّبِعوا المُرسَلين، اتَّبِعوا مَن لا يَسألُكُم أجراً وهُم مُهتَدون﴾. فَغَضِبَ قَومُهُ مِنه وقَتَلوه ظُلماً لِأنه دَعا إلى الله. وفي لَحظةِ دُخولِهِ الجَنّة، ماذا تَمَنّى هذا البَطَل؟ لم يَتَمَنَّ الانتِقامَ مِن قَومِهِ القاتِلين، بَل قال كَلِمةً تُذيبُ القَلبَ مِن رَحمَتِها: ﴿<b>يا لَيتَ قَومي يَعلَمونَ بِما غَفَرَ لي رَبّي وجَعَلَني مِنَ المُكرَمين</b>﴾! تَمَنّى لَو يَعرِفُ قاتِلوهُ نَعيمَ الإيمانِ لِيَدخُلوهُ مِثلَه!',
    en:'Today\'s hero is an ordinary, simple man whose story Allah immortalized in Surah Ya-Sin: <b>the believer of Ya-Sin</b> (known as Habib the carpenter)! 💚 He was in a town to which messengers came calling people to worship the One God, but the people denied and harmed them. This man lived at the far edge of the city, and when he heard of the messengers, he believed in them at once. Instead of sitting at home afraid, he did something brave: ﴾<b>And there came from the farthest end of the city a man, running</b>﴿ — he came rushing to support the messengers and call his people to faith! He told them: ﴾O my people, follow the messengers; follow those who ask of you no reward and are rightly guided﴿. His people grew angry at him and killed him unjustly because he called to Allah. In the moment of his entering Paradise, what did this hero wish for? He didn\'t wish revenge on his killers, but said words that melt the heart with their mercy: ﴾<b>If only my people knew of how my Lord has forgiven me and placed me among the honored</b>﴿! He wished his killers could know the bliss of faith so they could enter it like him!' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ يَتَمَنّى الخَيرَ لِمَن قَتَلوهُ بَدَلَ أن يَدعوَ علَيهِم؟» 🤔', en:'A question crosses your mind: "How could he wish good for those who killed him instead of cursing them?" 🤔' },
  logic:{
    ar:'لِأنَّ قَلبَهُ امتَلأَ بِنورِ الإيمانِ حتّى فاضَ رَحمةً على الجَميعِ — حتّى أعدائِه! حينَ ذاقَ حَلاوةَ الجَنّةِ والمَغفِرة، تَمَنّى مِن قَلبِهِ أن يَذوقَها كُلُّ النّاسِ، حتّى الذينَ ظَلَموه. هذا هو الإيمانُ الذي نُريدُ أن نَتَعَلَّمَهُ: لا يَجعَلُ صاحِبَهُ حاقِداً مُنتَقِماً، بَل مُحِبّاً لِلخَيرِ لِكُلِّ النّاس. ولاحِظ دَرسَين عَظيمَين: الأوَّل، أنه «جاءَ يَسعى» — لم يَكتَفِ بِالإيمانِ في قَلبِه، بَل سَعى لِيَدُلَّ غَيرَهُ على الخَير. البَطَلُ الحَقيقيُّ لا يَحتَفِظُ بِالكَنزِ لِنَفسِهِ بَل يُشارِكُه. الثّاني، أنه رَجُلٌ <b>عادِيٌّ</b> لا نَبِيٌّ ولا مَلِك، ومَع ذلكَ خَلَّدَ اللهُ اسمَهُ في القُرآنِ لِأنه ثَبَتَ ودَعا إلى الحَقّ. فَلا تَظُنَّ أنَّكَ صَغيرٌ أو عادِيّ: كَلِمةُ خَيرٍ تَقولُها، أو صَديقٌ تَدُلُّهُ على الصَّلاة، قد تَرفَعُكَ عِندَ اللهِ مَنزِلةً عَظيمة. وأجمَلُ ما في القِصّة: أنَّ الموتَ لم يَكُن نِهايةَ حَبيب، بَل بِدايةَ تَكريمِه. الظّالِمونَ ظَنّوا أنَّهُم أنهَوهُ، واللهُ أكرَمَهُ وأدخَلَهُ الجَنّة. هكذا يَنتَصِرُ المُؤمِنُ دائِماً.',
    en:'Because his heart filled with the light of faith until it overflowed with mercy for everyone — even his enemies! When he tasted the sweetness of Paradise and forgiveness, he wished from his heart that all people could taste it, even those who wronged him. This is the faith we want to learn: it doesn\'t make its owner spiteful and vengeful, but a lover of good for all people. Notice two great lessons: first, he "came running" — he wasn\'t content with faith in his heart, but strove to guide others to good. The true hero doesn\'t keep the treasure to himself but shares it. Second, he was an <b>ordinary</b> man, not a prophet or king, yet Allah immortalized his name in the Quran because he stood firm and called to the truth. So don\'t think you\'re small or ordinary: a word of good you say, or a friend you guide to prayer, may raise you to a great rank with Allah. And the most beautiful part of the story: death wasn\'t the end of Habib, but the beginning of his honoring. The oppressors thought they\'d finished him, but Allah honored him and admitted him to Paradise. This is how the believer always wins.' },
  myth:{ claim:{ ar:'«أنا شَخصٌ عادِيٌّ صَغير، لا أستَطيعُ أن أدعوَ أحَداً لِلخَير!»', en:'"I\'m an ordinary, small person — I can\'t call anyone to good!"' },
         bust:{ ar:'مُؤمِنُ يس كانَ رَجُلاً عادِيّاً، لكنه سَعى ودَعا قَومَهُ لِلحَقّ، فَخَلَّدَ اللهُ اسمَهُ في القُرآن. كَلِمةُ خَيرٍ مِنكَ قد تَرفَعُكَ مَنزِلةً عَظيمة.', en:'The believer of Ya-Sin was an ordinary man, but he strove and called his people to truth, so Allah immortalized his name in the Quran. A word of good from you may raise you to a great rank.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَعناه', en:'Match each thing to its meaning' },
    pairs:[
      { tool:{ar:'«رَجُلٌ يَسعى»',en:'"A man running"'}, job:{ar:'سَعى لِنَصرِ الحَقِّ ودَعوةِ قَومِه',en:'Strove to support truth and call his people'} },
      { tool:{ar:'«اتَّبِعوا المُرسَلين»',en:'"Follow the messengers"'}, job:{ar:'دَعوَتُهُ الشُّجاعةُ لِقَومِه',en:'His brave call to his people'} },
      { tool:{ar:'«يا لَيتَ قَومي يَعلَمون»',en:'"If only my people knew"'}, job:{ar:'تَمَنّى الخَيرَ حتّى لِقاتِليه',en:'He wished good even for his killers'} },
      { tool:{ar:'دُخولُهُ الجَنّة',en:'His entering Paradise'}, job:{ar:'تَكريمُ اللهِ لِمَن ثَبَتَ ودَعا',en:'Allah\'s honoring of one who stood firm and called'} },
    ] },
  reflection:{
    ayah:'﴿قِيلَ ادْخُلِ الْجَنَّةَ ۖ قَالَ يَا لَيْتَ قَوْمِي يَعْلَمُونَ ۝ بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ الْمُكْرَمِينَ﴾',
    ref:{ ar:'سورة يس · ٢٦–٢٧', en:'Surah Ya-Sin · 26–27' },
    explain:{
      ar:'انظُر إلى قَلبِ هذا المُؤمِنِ النَّقِيّ: في أوَّلِ لَحظةٍ يَدخُلُ فيها الجَنّة، لم يُفَكِّر إلّا في هِدايةِ قَومِه! «يا لَيتَ قَومي يَعلَمون» — لَيتَهُم يَعرِفونَ هذا النَّعيمَ فَيُؤمِنوا. هذِهِ هي رَحمةُ المُؤمِنِ الحَقّ: يُحِبُّ الخَيرَ لِلنّاسِ حتّى لِمَن أساءَ إلَيه. وفيها دَرسٌ: الدّاعي إلى اللهِ لا يَيأَسُ ولا يَحقِد، بَل يَتَمَنّى الهِدايةَ لِلجَميع. فَكُن مِثلَهُ: ادعُ لِأصحابِكَ بِالهِدايةِ، وتَمَنَّ لَهُم ما تَتَمَنّاهُ لِنَفسِك، تَكُن مِنَ المُكرَمينَ عِندَ الله.',
      en:'Look at the heart of this pure believer: in the very first moment he enters Paradise, he thinks only of guiding his people! "If only my people knew" — if only they knew this bliss so they would believe. This is the mercy of the true believer: he loves good for people, even those who wronged him. And there\'s a lesson: the one who calls to Allah doesn\'t despair or hold grudges, but wishes guidance for all. So be like him: pray for your friends\' guidance, and wish for them what you wish for yourself, and you\'ll be among the honored with Allah.' } },
  card:{ name:{ar:'مُؤمِنُ آلِ ياسين',en:'The Believer of Ya-Sin'}, meaning:{ar:'رَجُلٌ عادِيٌّ سَعى لِنَصرِ الحَقِّ ودَعا قَومَهُ، فَقَتَلوهُ فَأدخَلَهُ اللهُ الجَنّة — وتَمَنّى الهِدايةَ حتّى لِقاتِليه',en:'An ordinary man who strove to support the truth and called his people; they killed him and Allah admitted him to Paradise — and he wished guidance even for his killers'} },
  proof:{ ar:'لَستُ عادِيّاً صَغيراً: كَلِمةُ خَيرٍ أدعو بِها قد تَرفَعُني عِندَ الله', en:'I\'m not ordinary or small: a word of good I share may raise me with Allah' },
  dua:{ ar:'اللهُمَّ اهدِ قَومي وأحبابي، واجعَلني مِنَ المُكرَمينَ في جَنَّتِك', en:'O Allah, guide my people and loved ones, and make me among the honored in Your Paradise' },
  mission:{ ar:'🏃 مُهِمّةُ البُطولة: كُن «داعِياً صَغيراً» مِثلَ مُؤمِنِ يس: ادعُ صَديقاً لِيُصَلِّيَ مَعَك، أو عَلِّم أخاكَ الصَّغيرَ آيةً أو دُعاءً — وادعُ اللهَ بِالهِدايةِ لِمَن تُحِبّ.', en:'🏃 Hero Mission: Be a "little caller" like the believer of Ya-Sin: invite a friend to pray with you, or teach your younger sibling a verse or du\'a — and pray to Allah for the guidance of those you love.' },
  badge:{ icon:'💚', color:'#1E8C7E', title:{ ar:'الدّاعي إلى الخَير', en:'Caller to Good' } }
},

/* ───────────── 11 · Mus'ab ibn Umayr — From Luxury to Faith ───────────── */
/* ───────────── 11 · The Believer Who Faces the Dajjal at the End of Time ───────────── */
{
  id:'dajjal', num:11, icon:'🧔', emoji:'🛡️', color:'#3D5A80',
  title:{ ar:'الرَّجُلُ الذي يُكَذِّبُ الدَّجّال', en:'The Man Who Defies the Dajjal' },
  narration:{
    ar:'بَطَلُنا اليومَ لَم يُولَد بَعدُ! 🛡️ إنَّهُ رَجُلٌ مُؤمِنٌ سَيَعيشُ في آخِرِ الزَّمان، أخبَرَنا النَّبِيُّ ﷺ عَنهُ قَبلَ أن يُخلَق! في آخِرِ الزَّمانِ يَخرُجُ <b>المَسيحُ الدَّجّال</b> — وهو أعظَمُ فِتنةٍ (اختِبارٍ) عَرَفَتها البَشَرِيّة — يَدَّعي الرُّبوبِيّةَ ويُري النّاسَ عَجائِبَ يُخَيِّلُها اللهُ على يَدَيهِ ابتِلاءً. لكن حينَ يُريدُ دُخولَ المَدينة، يَخرُجُ إلَيهِ <b>رَجُلٌ مِن خَيرِ النّاس</b> فَيَقولُ بِكُلِّ شَجاعة: «<b>أشهَدُ أنَّكَ الدَّجّالُ الذي حَدَّثَنا عَنهُ رَسولُ اللهِ ﷺ</b>»! فَيَغضَبُ الدَّجّالُ ويُريدُ أن يُخيفَ النّاسَ بِه، فَيَقتُلُهُ ثُمَّ <b>يُحييهِ اللهُ</b> (يُظهِرُ الدَّجّالُ أنَّهُ أحياهُ خُدعةً). فَماذا يَقولُ الرَّجُلُ بَعدَ أن يَرجِعَ حَيّاً؟ تَزدادُ بَصيرَتُهُ ويَقينُهُ فَيَقول: «<b>واللهِ ما ازدَدتُ فيكَ إلّا بَصيرةً</b>» — أي: صِرتُ أكثَرَ يَقيناً أنَّكَ الدَّجّالُ الكَذّاب! فَيُحاوِلُ الدَّجّالُ قَتلَهُ مَرَّةً أُخرى <b>فَلا يَستَطيع</b>، لِأنَّ اللهَ حَماهُ! ويُخبِرُنا النَّبِيُّ ﷺ أنَّ هذا الرَّجُلَ هو <b>أعظَمُ النّاسِ شَهادةً عِندَ رَبِّ العالَمين</b> (رواه مسلم)!',
    en:'Today’s hero hasn’t been born yet! 🛡️ He is a believing man who will live at the end of time — the Prophet ﷺ told us about him before he is even created! At the end of time, <b>al-Masih ad-Dajjal</b> (the Antichrist) will appear — the greatest trial humanity has ever known — falsely claiming lordship and showing people wonders that Allah lets appear at his hands as a test. But when he wants to enter Madinah, <b>a man among the best of people</b> will go out to him and say with full courage: “<b>I testify that you are the Dajjal whom the Messenger of Allah ﷺ told us about</b>!” The Dajjal will be enraged and want to frighten people through him, so he will kill him, then <b>Allah will bring him back to life</b> (the Dajjal makes it appear that he revived him — a deception). What does the man say after returning to life? His insight and certainty only grow, and he says: “<b>By Allah, I have never been more certain about you than now</b>” — meaning: I am now even more sure you are the lying Dajjal! The Dajjal will try to kill him a second time <b>but will not be able to</b>, because Allah protects him! And the Prophet ﷺ tells us that this man is <b>the greatest of people in martyrdom in the sight of the Lord of the Worlds</b> (Muslim)!' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «إذا كانَ الدَّجّالُ يُحيي المَوتى ويُري العَجائِب، ألا يَدُلُّ ذلك أنَّهُ صادِق؟» 🤔', en:'A question crosses your mind: “If the Dajjal revives the dead and shows wonders, doesn’t that prove he’s truthful?” 🤔' },
  logic:{
    ar:'أبَداً! وهذا بِالضَّبطِ ما فَهِمَهُ الرَّجُلُ المُؤمِنُ فَثَبَت! تَعالَ نُفَكِّر مَعاً: الدَّجّالُ عاجِزٌ ضَعيفٌ رغمَ عَجائِبِه: مَكتوبٌ بَينَ عَينَيهِ «كافِر» يَقرَؤُها كُلُّ مُؤمِن، وهو <b>أعوَر</b> (عَينُهُ واحِدة) ورَبُّكَ ليسَ بِأعوَر، ولا يَستَطيعُ دُخولَ مَكّةَ والمَدينة، وسَيُهلِكُ على يَدِ عيسى عليه السلام. فعَجائِبُهُ مُجَرَّدُ <b>اختِبار</b> مِنَ اللهِ لِيَظهَرَ الصّادِقُ مِنَ الكاذِب، ولَيسَت دَليلَ صِدق، كَما أنَّ ساحِرَ الألعابِ لا يَصيرُ صادِقاً لِأنَّهُ أدهَشَك! ولاحِظ سِرَّ ثَباتِ الرَّجُلِ العَظيم: لِأنَّهُ كانَ <b>يَعرِفُ عُلومَ دينِه</b>! النَّبِيُّ ﷺ وَصَفَ الدَّجّالَ بِدِقّة، فَحينَ رآهُ الرَّجُلُ عَرَفَهُ فَوراً ولم يَنخَدِع. وهذا دَرسُكَ أنتَ اليوم: <b>العِلمُ دِرعٌ يَحميكَ مِنَ الخُدَع</b>. مَن عَرَفَ دينَهُ جَيِّداً لا تَخدَعُهُ الأكاذيبُ مَهما بَدَت بَرّاقة، ومَن جَهِلَ دينَهُ سَهُلَ خِداعُه. ولِذلكَ عَلَّمَنا النَّبِيُّ ﷺ أن نَستَعيذَ مِنَ الدَّجّالِ في كُلِّ صَلاة، وأن نَحفَظَ أوَّلَ عَشرِ آياتٍ مِن سورةِ الكَهفِ (تَحمي مِنَ الدَّجّال). فَالبَطَلُ لا يُولَدُ بَطَلاً فَجأةً، بَل يُعِدُّ نَفسَهُ بِالعِلمِ والإيمانِ مِنَ الآن.',
    en:'Never! And that’s exactly what the believing man understood, so he stood firm! Let’s think together: the Dajjal is weak and powerless despite his wonders — written between his eyes is “<b>kafir</b> (disbeliever)” which every believer can read; he is <b>one-eyed</b> while your Lord is not; he cannot enter Makkah or Madinah; and he will be destroyed at the hands of ‘Isa (Jesus, peace be upon him). So his wonders are merely a <b>test</b> from Allah to distinguish the truthful from the liar — not proof of truthfulness, just as a stage magician doesn’t become truthful because he amazed you! And notice the secret of the man’s great steadfastness: he <b>knew the teachings of his religion</b>! The Prophet ﷺ described the Dajjal precisely, so when the man saw him, he recognized him at once and wasn’t deceived. This is your lesson today: <b>knowledge is a shield that protects you from deception</b>. Whoever knows his religion well isn’t fooled by lies however shiny they look; whoever is ignorant of his religion is easily deceived. That’s why the Prophet ﷺ taught us to seek refuge from the Dajjal in every prayer, and to memorize the first ten verses of Surah al-Kahf (they protect from the Dajjal). A hero isn’t suddenly born a hero — he prepares himself with knowledge and faith starting now.' },
  myth:{ claim:{ ar:'«لا نَستَطيعُ فِعلَ شَيءٍ أمامَ خُدَعِ الدَّجّالِ العَظيمة!»', en:'“We can’t do anything against the Dajjal’s mighty tricks!”' },
         bust:{ ar:'بَل الرَّجُلُ المُؤمِنُ ثَبَتَ بِالعِلمِ والإيمان، وصارَ أعظَمَ النّاسِ شَهادةً. وأعطانا النَّبِيُّ ﷺ سِلاحَنا: مَعرِفةَ صِفاتِهِ، وسورةَ الكَهف، ودُعاءَ الاستِعاذة.', en:'Rather, the believing man stood firm through knowledge and faith and became the greatest of people in martyrdom. The Prophet ﷺ gave us our weapons: knowing the Dajjal’s signs, Surah al-Kahf, and the dua of seeking refuge.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'الرَّجُلُ المُؤمِن',en:'The believing man'}, job:{ar:'مِن خَيرِ النّاسِ ثَبَتَ أمامَ الدَّجّال',en:'Among the best, firm before the Dajjal'} },
      { tool:{ar:'«أشهَدُ أنَّكَ الدَّجّال»',en:'“I testify you are the Dajjal”'}, job:{ar:'عَرَفَهُ لِأنَّ النَّبِيَّ ﷺ وَصَفَه',en:'He knew him from the Prophet’s ﷺ description'} },
      { tool:{ar:'«ما ازدَدتُ فيكَ إلّا بَصيرة»',en:'“I’m only more certain about you”'}, job:{ar:'ثَباتٌ بَعدَ أن أحياهُ الله',en:'Steadfast after Allah revived him'} },
      { tool:{ar:'أعظَمُ النّاسِ شَهادةً',en:'Greatest of people in martyrdom'}, job:{ar:'جَزاءُ ثَباتِهِ عِندَ الله',en:'The reward of his steadfastness with Allah'} },
    ] },
  reflection:{
    ayah:'﴿إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلَائِكَةُ أَلَّا تَخَافُوا وَلَا تَحْزَنُوا﴾',
    ref:{ ar:'سورة فُصِّلَت · ٣٠', en:'Surah Fussilat · 30' },
    explain:{
      ar:'هذِهِ الآيةُ وَصْفٌ دَقيقٌ لِبَطَلِنا: قالَ «رَبُّنا اللهُ» <b>ثُمَّ استَقامَ</b> — أي ثَبَتَ ولم يَتَراجَع. وما جَزاؤُه؟ تَنزِلُ المَلائِكةُ تُطَمْئِنُه: «ألّا تَخافوا ولا تَحزَنوا». فَالثَّباتُ لَيسَ أن تَكونَ بِلا خَوف، بَل أن تَثبُتَ رغمَ الخَوفِ لِأنَّ اللهَ مَعَك. وأنتَ لَستَ مُطالَباً بِلقاءِ الدَّجّالِ اليوم، بَل بِأن تَبدَأَ استِقامَتَكَ الصَّغيرةَ الآن: صَلاتُكَ في وَقتِها، صِدقُكَ مَع النّاس، ثَباتُكَ على صَلاتِكَ ولو سَخِرَ مِنكَ أحَد. مَن استَقامَ في الصَّغائِر، ثَبَّتَهُ اللهُ في الكَبائِر.',
      en:'This verse precisely describes our hero: he said “our Lord is Allah” <b>then remained steadfast</b> — firm, never retreating. And his reward? The angels descend to reassure him: “do not fear, nor grieve.” Steadfastness isn’t being without fear; it’s standing firm despite fear, because Allah is with you. And you aren’t asked to face the Dajjal today — but to begin your small steadfastness now: your prayer on time, your honesty with people, holding to your prayer even if someone mocks you. Whoever is steadfast in small things, Allah makes firm in great ones.' } },
  card:{ name:{ar:'الثّابِتُ أمامَ الدَّجّال',en:'The One Firm Before the Dajjal'}, meaning:{ar:'رَجُلٌ مُؤمِنٌ في آخِرِ الزَّمانِ يُكَذِّبُ الدَّجّالَ بِعِلمِهِ ويَقينِه، ويَزدادُ ثَباتاً بَعدَ البَلاء — أعظَمُ النّاسِ شَهادةً عِندَ الله',en:'A believing man at the end of time who defies the Dajjal through knowledge and certainty, growing firmer after the trial — the greatest of people in martyrdom with Allah'} },
  proof:{ ar:'العِلمُ بِديني دِرعٌ يَحميني مِنَ الخُدَع، واللهُ يُثَبِّتُ مَن استَقام', en:'Knowledge of my religion is a shield from deception, and Allah keeps firm whoever stays steadfast' },
  dua:{ ar:'اللهُمَّ إنّي أعوذُ بِكَ مِن فِتنةِ المَسيحِ الدَّجّال', en:'O Allah, I seek refuge in You from the trial of the Masih ad-Dajjal' },
  mission:{ ar:'🧔 مُهِمّةُ البُطولة: تَسَلَّح بِسِلاحِ الرَّجُلِ المُؤمِن: احفَظ دُعاءَ «اللهُمَّ إنّي أعوذُ بِكَ مِن فِتنةِ المَسيحِ الدَّجّال» وقُلهُ في كُلِّ صَلاةٍ قَبلَ السَّلام، واحفَظ ثَلاثَ عَلاماتٍ لِلدَّجّالِ حتّى لا تَنخَدِعَ بِه (أعوَر، مَكتوبٌ بَينَ عَينَيهِ كافِر، لا يَدخُلُ مَكّةَ والمَدينة).', en:'🧔 Hero Mission: Arm yourself with the believing man’s weapons: memorize the dua “O Allah, I seek refuge in You from the trial of the Masih ad-Dajjal” and say it in every prayer before the salam, and memorize three signs of the Dajjal so you won’t be deceived (one-eyed, “kafir” written between his eyes, cannot enter Makkah or Madinah).' },
  badge:{ icon:'🛡️', color:'#3D5A80', title:{ ar:'دِرعُ اليَقين', en:'Shield of Certainty' } }
},

/* ───────────── 12 · Mus'ab ibn Umayr — From Luxury to Faith ───────────── */
{
  id:'musab', num:12, icon:'🎖️', emoji:'🤍', color:'#7B5EA7',
  title:{ ar:'مُصعَبُ بنُ عُمَير — مِنَ التَّرَفِ إلى الفِداء', en:'Mus\'ab ibn Umayr — From Luxury to Sacrifice' },
  narration:{
    ar:'نَختِمُ رِحلةَ الأبطالِ بِشابٍّ سَيَبقى مِثالاً خالِداً: <b>مُصعَبُ بنُ عُمَير</b> رضي الله عنه! 🤍 كانَ في مَكّةَ أجمَلَ شابٍّ وأكثَرَهُم نَعيماً، يَلبَسُ أفخَرَ الثِّياب، وتُدَلِّلُهُ أُمُّهُ الغَنِيّةُ بِكُلِّ ما يَشتَهي، حتّى كانَ النّاسُ يَقولون: ما رَأينا شابّاً أنعَمَ مِن مُصعَب. ثُمَّ سَمِعَ بِالإسلامِ فَآمَنَ بِهِ قَلبُهُ، فَتَغَيَّرَت حَياتُهُ كُلُّها! لَمّا عَلِمَت أُمُّهُ حَبَسَتهُ ومَنَعَت عنهُ المالَ والطَّعامَ لِتُرجِعَهُ عنِ الإسلام، لكنه ثَبَتَ واختارَ <b>دينَهُ على كُلِّ نَعيمِه</b>. خَرَجَ مِن قَصرِ التَّرَفِ بِثَوبٍ واحِدٍ قَديم، تارِكاً المالَ والجاهَ مِن أجلِ الله. اختارَهُ النَّبِيُّ ﷺ لِيَكونَ <b>أوَّلَ سَفيرٍ لِلإسلام</b> يُعَلِّمُ أهلَ المَدينةِ القُرآن، فَأسلَمَ على يَدَيهِ خَلقٌ كَثير. ثُمَّ استُشهِدَ في غَزوةِ أُحُدٍ وهو يَحمِلُ الرّايةَ بِكُلِّ ثَبات. ولَمّا أرادوا تَكفينَهُ، لم يَجِدوا إلّا ثَوباً واحِداً قَصيراً: إن غَطَّوا رَأسَهُ بَدَت قَدَماهُ، وإن غَطَّوا قَدَمَيهِ بَدا رَأسُه! هذا الشّابُّ الذي كانَ يَلبَسُ أفخَرَ الثِّياب، ماتَ شَهيداً بِثَوبٍ لا يَكفي جَسَدَه — لكنه رَبِحَ الجَنّةَ والخُلودَ والذِّكرَ الحَسَنَ إلى الأبَد.',
    en:'We conclude the Journey of the Heroes with a young man who remains an eternal example: <b>Mus\'ab ibn Umayr</b> (may Allah be pleased with him)! 🤍 In Makkah he was the most handsome and pampered youth, wearing the finest clothes, his wealthy mother indulging his every desire, until people said: we have never seen a youth more pampered than Mus\'ab. Then he heard of Islam and his heart believed, and his whole life changed! When his mother found out, she imprisoned him and cut off money and food to turn him from Islam, but he held firm and chose <b>his faith over all his comfort</b>. He left the palace of luxury in a single old garment, abandoning wealth and status for Allah\'s sake. The Prophet ﷺ chose him to be <b>the first ambassador of Islam</b>, teaching the people of Madinah the Quran, and many embraced Islam at his hands. Then he was martyred at the Battle of Uhud, carrying the banner with full steadfastness. When they wanted to shroud him, they found only one short garment: if they covered his head, his feet showed; if they covered his feet, his head showed! This young man who once wore the finest clothes died a martyr in a garment too short for his body — but he won Paradise, eternity, and beautiful remembrance forever.' },
  shubha:{ ar:'سُؤالٌ يَخطُرُ بِبالِك: «كَيفَ يَترُكُ شابٌّ غَنِيٌّ كُلَّ نَعيمِهِ ويَرضى بِالفَقرِ مِن أجلِ الدّين؟» 🤔', en:'A question crosses your mind: "How does a rich young man leave all his comfort and accept poverty for his religion?" 🤔' },
  logic:{
    ar:'لِأنَّ مُصعَباً اكتَشَفَ كَنزاً أغلى مِن كُلِّ ذَهَبِ الدُّنيا: <b>حَلاوةَ الإيمانِ وقُربَ الله</b>. مَن ذاقَ هذِهِ الحَلاوةَ لا تُساوي عِندَهُ كُنوزُ الأرضِ شَيئاً. لم يَكُن مُصعَبٌ فَقيراً مَجبوراً، بَل غَنِيّاً <b>اختارَ</b> أن يَترُكَ الغِنى مِن أجلِ ما هو أبقى. وهذا أصعَبُ أنواعِ الثَّبات: أن تَملِكَ كُلَّ شَيءٍ ثُمَّ تَترُكَهُ لِلهِ بِرِضا. ودَرسُهُ خاتِمةٌ جَميلةٌ لِرِحلَتِنا كُلِّها: كُلُّ أبطالِ هذِهِ الرِّحلةِ — الغُلامُ، وفِتيةُ الكَهف، والسَّحَرة، وآسِية، وإبراهيم، وبِلال، وآلُ ياسِر، وماشِطةُ فِرعَون، وخُبَيب، ومُؤمِنُ يس، والرَّجُلُ الذي يُكَذِّبُ الدَّجّال، ومُصعَب — جَمَعَهُم سِرٌّ واحِد: <b>عَرَفوا أنَّ الدّينَ أغلى مِنَ الدُّنيا كُلِّها</b>، فَثَبَتوا علَيهِ مَهما كانَ الثَّمَن. وانظُرِ النَّتيجةَ بَعدَ مِئاتِ السِّنين: أينَ القُصورُ التي تَرَكوها؟ زالَت. وأينَ أسماؤُهُم؟ خالِدةٌ نَذكُرُها بِالحُبِّ والفَخر، ونَدعو لَهُم، ونَتَعَلَّمُ مِنهُم. هذا هو رِبحُ الثَّبات. وأنتَ يا بَطَلُ المُستَقبَل: تَمَسَّك بِدينِكَ كَما تَمَسَّكوا، فَالدُّنيا تَزولُ والإيمانُ يَبقى، ولِقاءُ اللهِ خَيرٌ مِنَ الدُّنيا وما فيها.',
    en:'Because Mus\'ab discovered a treasure more precious than all the gold of the world: <b>the sweetness of faith and nearness to Allah</b>. Whoever tastes this sweetness finds the earth\'s treasures worth nothing beside it. Mus\'ab wasn\'t a poor man forced into it, but a rich man who <b>chose</b> to leave wealth for what is more lasting. This is the hardest kind of steadfastness: to own everything and then leave it for Allah contentedly. His lesson is a beautiful conclusion to our whole journey: all the heroes of this journey — the boy, the youth of the cave, the sorcerers, Asiya, Ibrahim, Bilal, the family of Yasir, the hair-comber of Pharaoh, Khubayb, the believer of Ya-Sin, the man who defies the Dajjal, and Mus\'ab — shared one secret: <b>they knew that religion is more precious than the whole world</b>, so they held firm to it whatever the price. And look at the result after hundreds of years: where are the palaces they left? Gone. And where are their names? Eternal, remembered with love and pride; we pray for them and learn from them. This is the profit of steadfastness. And you, future hero: hold to your faith as they held, for the world fades and faith remains, and meeting Allah is better than the world and all it contains.' },
  myth:{ claim:{ ar:'«الغِنى والنَّعيمُ أهَمُّ مِنَ الدّين، ولا أحَدَ يَترُكُهُما!»', en:'"Wealth and comfort matter more than religion — nobody gives them up!"' },
         bust:{ ar:'مُصعَبٌ كانَ أنعَمَ شابٍّ في مَكّة، فَتَرَكَ كُلَّ ذلكَ لِدينِهِ، وماتَ شَهيداً بِثَوبٍ قَصير — ورَبِحَ الجَنّةَ والخُلود. الدُّنيا تَزولُ والإيمانُ يَبقى.', en:'Mus\'ab was the most pampered youth in Makkah, yet he left it all for his faith and died a martyr in a short garment — winning Paradise and eternity. The world fades; faith remains.' } },
  match:{
    title:{ ar:'صِل كُلَّ شَيءٍ بِمَكانِهِ في القِصّة', en:'Match each thing to its place in the story' },
    pairs:[
      { tool:{ar:'مُصعَبٌ قَبلَ الإسلام',en:'Mus\'ab before Islam'}, job:{ar:'أنعَمُ شابٍّ في مَكّة',en:'The most pampered youth in Makkah'} },
      { tool:{ar:'مُصعَبٌ بَعدَ الإسلام',en:'Mus\'ab after Islam'}, job:{ar:'تَرَكَ التَّرَفَ لِأجلِ دينِه',en:'Left luxury for his faith'} },
      { tool:{ar:'أوَّلُ سَفيرٍ لِلإسلام',en:'First ambassador of Islam'}, job:{ar:'عَلَّمَ أهلَ المَدينةِ القُرآن',en:'Taught the people of Madinah the Quran'} },
      { tool:{ar:'الثَّوبُ القَصير',en:'The short garment'}, job:{ar:'كَفَنُ شَهيدٍ رَبِحَ الجَنّة',en:'The shroud of a martyr who won Paradise'} },
    ] },
  reflection:{
    ayah:'﴿مِّنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ۖ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُ وَمِنْهُم مَّن يَنتَظِرُ ۖ وَمَا بَدَّلُوا تَبْدِيلًا﴾',
    ref:{ ar:'سورة الأحزاب · ٢٣', en:'Surah Al-Ahzab · 23' },
    explain:{
      ar:'نَزَلَت هذِهِ الآيةُ في الثّابِتينَ الصّادِقينَ مِثلِ مُصعَب. تَأمَّل خِتامَها: ﴿<b>وما بَدَّلوا تَبديلاً</b>﴾ — أيْ ثَبَتوا على عَهدِهِم مَعَ اللهِ ولم يُغَيِّروا ولم يَتَراجَعوا أبَداً، مِنَ البِدايةِ إلى المَوت. هذا هو سِرُّ الأبطالِ كُلِّهِم في رِحلَتِنا: الثَّباتُ حتّى النِّهاية. والعَهدُ الذي علَينا نَحنُ اليوم: أن نَتَمَسَّكَ بِديننا، نُصَلّي، ونَصدُق، ونُحِبَّ اللهَ ورَسولَه، ولا نُبَدِّلَ ولا نَتَراجَع مَهما أغرَتنا الدُّنيا أو خَوَّفَنا النّاس. فَاعقِد العَزمَ مِنَ اليوم: «أنا على عَهدي مَعَ الله، ثابِتٌ على دينِهِ حتّى ألقاه».',
      en:'This verse was revealed about the steadfast and truthful, like Mus\'ab. Reflect on its ending: ﴾<b>and they did not alter by any alteration</b>﴿ — they held to their covenant with Allah and never changed or retreated, from beginning to death. This is the secret of all the heroes in our journey: steadfastness until the end. And the covenant upon us today: to hold to our religion, to pray, to be truthful, to love Allah and His Messenger, and not to change or retreat however much the world tempts us or people frighten us. So resolve from today: "I am upon my covenant with Allah, firm on His religion until I meet Him."' } },
  card:{ name:{ar:'مُصعَبُ بنُ عُمَير',en:'Mus\'ab ibn Umayr'}, meaning:{ar:'أنعَمُ شابٍّ في مَكّةَ تَرَكَ التَّرَفَ كُلَّهُ لِدينِه، فَصارَ أوَّلَ سَفيرٍ لِلإسلامِ ثُمَّ شَهيدَ أُحُد — الدُّنيا تَزولُ والإيمانُ يَبقى',en:'The most pampered youth in Makkah who left all luxury for his faith, became Islam\'s first ambassador, then a martyr at Uhud — the world fades, faith remains'} },
  proof:{ ar:'الدُّنيا تَزولُ والإيمانُ يَبقى — أتَمَسَّكُ بِديني مَهما كانَ الثَّمَن', en:'The world fades and faith remains — I hold to my religion whatever the price' },
  dua:{ ar:'اللهُمَّ ثَبِّتني على دينِكَ حتّى ألقاك، ولا تُزِغ قَلبي بَعدَ إذ هَدَيتَني', en:'O Allah, keep me firm on Your religion until I meet You, and let not my heart deviate after You have guided me' },
  mission:{ ar:'🎖️ مُهِمّةُ الخِتام: اكتُب «عَهدَ بَطَل» في دَفتَرِك: «أنا أتَمَسَّكُ بِديني، أُصَلّي وأصدُقُ وأُحِبُّ اللهَ، ثابِتٌ كَالأبطال». ووَقِّعهُ بِاسمِك. وهَنيئاً لَكَ إتمامُ رِحلةِ الأبطالِ وكُلِّ رِحلاتِ العقيدة! 🏆', en:'🎖️ Final Mission: Write a "hero\'s covenant" in your journal: "I hold to my religion, I pray, I am truthful, I love Allah, firm like the heroes." Sign it with your name. Congratulations on completing the Journey of the Heroes and all the journeys of faith! 🏆' },
  badge:{ icon:'🤍', color:'#7B5EA7', title:{ ar:'الثّابِتُ حتّى اللِّقاء', en:'Firm Until the Meeting' } }
},
];
